source:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff either $A = \emptyset$ or there is
  an enumeration of~$A$. We say that $A$ is !!{nonenumerable} iff $A$
  is not !!{enumerable}.
\end{defn}

target:
\begin{defn}
  \ollabel{defn:enumerable}
  يو سټ~$A$ هله او يوازې هله !!{enumerable} دے چې يا
  $A = \emptyset$ وي يا د~$A$ يوه شمېرنه وي۔ وايو چې $A$ هله
  او يوازې هله !!{nonenumerable} دے چې $A$ !!{enumerable} نۀ وي۔
\end{defn}

source:
\begin{explain}
So a set is !!{enumerable} iff it is empty or you can use an
enumeration to count out its !!{element}s.
\end{explain}

target:
\begin{explain}
نو يو سټ هله او يوازې هله !!{enumerable} دے چې تش وي يا ئې
!!{element}s په يوه شمېرنه شمېرلے شئ۔
\end{explain}

source:
\begin{ex}
A function enumerating the natural numbers is simply the identity
function $\Id{\Nat} \colon \Nat \to \Nat$ given by $\Id{\Nat}(n) = n$. A
function enumerating the \emph{positive} natural numbers, $\Nat^+ =
\Nat \setminus \{0\}$, is the function $g(n) = n + 1$, i.e., the
successor function.
\end{ex}

\begin{prob}
Show that a set $A$ is !!{enumerable} iff either $A = \emptyset$ or
there is !!a{surjection} $f\colon \Nat \to A$. Show that $A$ is
!!{enumerable} iff there is !!a{injection} $g\colon A \to \Nat$. 
\end{prob}

target:
\begin{prob}
وښيئ چې يو سټ $A$ هله او يوازې هله !!{enumerable} دے چې يا
$A = \emptyset$ وي يا يوه !!a{surjection} $f\colon \Nat \to A$
وي۔ وښيئ چې $A$ هله او يوازې هله !!{enumerable} دے چې يوه
!!a{injection} $g\colon A \to \Nat$ وي۔
\end{prob}

source:
\begin{ex}
The functions $f\colon \Nat \to \Nat$ and $g \colon \Nat \to \Nat$
given by
\begin{align*}
  f(n) & = 2n \text{ and}\\
  g(n) & = 2n+1
\end{align*}
respectively enumerate the even natural numbers and the odd natural
numbers. But neither is !!{surjective}, so neither is an enumeration
of $\Nat$.
\end{ex}

target:
\begin{ex}
تابعې $f\colon \Nat \to \Nat$ او $g \colon \Nat \to \Nat$ چې
په ترتيب سره په لاندې ډول ورکړل شوې دي:
\begin{align*}
  f(n) & = 2n \text{ او}\\
  g(n) & = 2n+1
\end{align*}
جفت طبيعي عددونه او طاق طبيعي عددونه شمېري۔ خو له دواړو يوه هم
!!{surjective} نۀ ده، نو يوه هم د $\Nat$ شمېرنه نۀ ده۔
\end{ex}

