\begin{thm}[Arithmetical induction]\ollabel{thm:dedinfiniteinduction}
Let $N, s, o$ comprise a Dedekind algebra. Then for any set $X$:  
	\begin{center}
		if $o \in X$ and $(\forall {n} \in N \cap X){s}({n}) \in X$, {then} $N \subseteq X$.
	\end{center}
\end{thm}

target:
\begin{thm}[رياضي استقرا]\ollabel{thm:dedinfiniteinduction}
فرض کړئ $N, s, o$ يو ډېډېکېنډ الجبر جوړوي۔ بيا د هر سټ $X$ دپاره:
	\begin{center}
		که $o \in X$ او $(\forall {n} \in N \cap X){s}({n}) \in X$ وي، {نو} $N \subseteq X$۔
	\end{center}
\end{thm}

source:
\begin{proof}
By the definition of a Dedekind algebra, $N = \closureofunder{s}{o}$.
Now if both ${o} \in X$ and $(\forall {n} \in N)(n \in X \lif
{s}({n}) \in X)$, then $N = \closureofunder{s}{o} \subseteq X$.
\end{proof}

target:
\begin{proof}
د ډېډېکېنډ الجبر د تعريف له مخې $N = \closureofunder{s}{o}$۔ اوس
که هم ${o} \in X$ او هم $(\forall {n} \in N)(n \in X \lif
{s}({n}) \in X)$ وي، نو $N = \closureofunder{s}{o} \subseteq X$۔
\end{proof}

