\begin{intro}
You may be familiar with different terminology and symbols than the
ones we use above. Logic texts (and teachers) commonly use either
$\sim$, $\neg$, and~!\ for ``negation'', $\wedge$, $\cdot$, and $\&$
for ``conjunction''.  Commonly used symbols for the ``conditional'' or
``implication'' are $\rightarrow$, $\Rightarrow$, and $\supset$.
\iftag{prvIff,defIff}{Symbols for ``biconditional,'' ``bi-implication,''
  or ``(material) equivalence'' are $\leftrightarrow$,
  $\Leftrightarrow$, and $\equiv$.}{}
\iftag{prvFalse,defFalse}{The $\lfalse$ symbol is variously called
  ``falsity,'' ``falsum,'' ``absurdity,'' or ``bottom.''}{}
\iftag{prvTrue,defTrue}{The $\ltrue$ symbol is variously called
  ``truth,'' ``verum,'' or ``top.''}{}
\end{intro}

target:
\begin{intro}
کېدے شي تاسو له هغو اصطلاحاتو او نښو سره بلد يئ چې زموږ له پورته
کارولو سره توپير لري۔ د منطق متنونه، او ښوونکي، عموماً د ``نفي''
دپاره $\sim$، $\neg$ او~!، او د ``عطف'' دپاره $\wedge$، $\cdot$ او
$\&$ کاروي۔ د ``شرطي'' يا ``استلزام'' عامې نښې $\rightarrow$،
$\Rightarrow$ او $\supset$ دي۔
\iftag{prvIff,defIff}{د ``دوه اړخيز شرطي''، ``دوه اړخيز استلزام''
  يا ``(مادي) هم ارزښت'' نښې $\leftrightarrow$،
  $\Leftrightarrow$ او $\equiv$ دي۔}{}
\iftag{prvFalse,defFalse}{د $\lfalse$ نښې ته په بېلو ځايونو کښې
  ``دروغوالے''، ``فالسوم''، ``محال'' يا ``ښکته'' ويل کېږي۔}{}
\iftag{prvTrue,defTrue}{د $\ltrue$ نښې ته په بېلو ځايونو کښې
  ``رښتياوالے''، ``ويروم'' يا ``پورته'' ويل کېږي۔}{}
\end{intro}

