source:
\begin{prop}\ollabel{prop:explicit-inc}
  If $\Gamma \Proves !A$ and $\lnot !A \in \Gamma$, then $\Gamma$ is
  inconsistent.
\end{prop}

target:
\begin{prop}\ollabel{prop:explicit-inc}
  که $\Gamma \Proves !A$ او $\lnot !A \in \Gamma$ وي، نو $\Gamma$
  ناسازګار دے۔
\end{prop}

source:
\begin{proof}
  Suppose $\Gamma \Proves !A$ and $\lnot !A \in \Gamma$.  Then there
  is !!a{derivation}~$\delta$ of~$!A$ from~$\Gamma$. Consider this
    simple application of the $\Elim{\lnot}$ rule:
  \begin{prooftree}
    \AxiomC{$\lnot !A$}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta$}
    \DeduceC{$!A$}
    \RightLabel{\Elim{\lnot}}
    \BinaryInfC{$\lfalse$}
  \end{prooftree}
  Since $\lnot !A \in \Gamma$, all !!{undischarged} assumptions are
  in~$\Gamma$, this shows that $\Gamma \Proves \lfalse$.
\end{proof}

target:
\begin{proof}
  فرض کړئ $\Gamma \Proves !A$ او $\lnot !A \in \Gamma$۔ بيا
  له~$\Gamma$ څخه د~$!A$ کوم !!a{derivation}~$\delta$ شته۔ د
  $\Elim{\lnot}$ قاعدې دا ساده کارونه وګورئ:
  \begin{prooftree}
    \AxiomC{$\lnot !A$}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta$}
    \DeduceC{$!A$}
    \RightLabel{\Elim{\lnot}}
    \BinaryInfC{$\lfalse$}
  \end{prooftree}
  ځکه $\lnot !A \in \Gamma$ او ټولې !!{undischarged} فرضيې
  په~$\Gamma$ کښې دي، دا $\Gamma \Proves \lfalse$ ښيي۔
\end{proof}

source:
\begin{prop}\ollabel{prop:provability-exhaustive}
  If $\Gamma \cup \{!A\}$ and $\Gamma \cup \{\lnot !A\}$ are both
  inconsistent, then $\Gamma$ is inconsistent.
\end{prop}

target:
\begin{prop}\ollabel{prop:provability-exhaustive}
  که $\Gamma \cup \{!A\}$ او $\Gamma \cup \{\lnot !A\}$ دواړه
  ناسازګار وي، نو $\Gamma$ ناسازګار دے۔
\end{prop}

source:
\begin{proof}
There are !!{derivation}s $\delta_1$ and $\delta_2$ of~$\lfalse$ from
  $\Gamma \cup \{ !A \}$ and $\lfalse$ from $\Gamma \cup \{ \lnot !A
  \}$, respectively. We can then !!{derive}
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{\lnot !A}{2}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{2}
\UnaryInfC{$\lnot \lnot !A$}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_1$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
Since the assumptions $!A$ and $\lnot !A$ are !!{discharged}, this is
!!a{derivation} of~$\lfalse$ from~$\Gamma$ alone. Hence $\Gamma$ is
inconsistent.
\end{proof}

target:
\begin{proof}
په ترتيب سره له~$\Gamma \cup \{ !A \}$ څخه د~$\lfalse$ او له
$\Gamma \cup \{ \lnot !A \}$ څخه د~$\lfalse$~!!{derivation}s
$\delta_1$ او~$\delta_2$ شته۔ بيا داسې !!{derive} کولے شو:
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{\lnot !A}{2}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{2}
\UnaryInfC{$\lnot \lnot !A$}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_1$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
ځکه فرضيې~$!A$ او~$\lnot !A$~!!{discharged} شوې دي، دا يوازې
له~$\Gamma$ څخه د~$\lfalse$ يو !!a{derivation} دے۔ نو $\Gamma$
ناسازګار دے۔
\end{proof}

