      \DisplayProof\qquad\bottomAlignProof
      \AxiomC{$!B$}
      \RightLabel{\Intro{\lif}}
      \UnaryInfC{$!A \lif !B$}
    \end{prooftree}
    Note that $\Intro{\lif}$ may, but does not have to, !!{discharge} the
    assumption~$!A$.
  \end{enumerate}
\end{proof}

target:
  \item دا د لاندې دوو !!{derivation}s په وسيله ښودل کېږي:
    \begin{prooftree}
      \AxiomC{$\lnot !A$}
      \AxiomC{$\Discharge{!A}{1}$}
      \RightLabel{\Elim{\lnot}}
      \BinaryInfC{$\lfalse$}
      \RightLabel{\FalseInt}
      \UnaryInfC{$!B$}
      \DischargeRule{\Intro{\lif}}{1}
      \UnaryInfC{$!A \lif !B$}
      \DisplayProof\qquad\bottomAlignProof
      \AxiomC{$!B$}
      \RightLabel{\Intro{\lif}}
      \UnaryInfC{$!A \lif !B$}
    \end{prooftree}
    پام وکړئ چې $\Intro{\lif}$ د فرضيې~$!A$~!!{discharge} کولے
    شي، خو لازمه نۀ ده چې و ئې باسي۔
  \end{enumerate}
\end{proof}

