\begin{prop}[Transitivity]
\ollabel{prop:transitivity}
If $\Gamma \Proves !A$ and $\{!A\} \cup
\Delta \Proves !B$, then $\Gamma \cup \Delta \Proves !B$.
\end{prop}

target:
\begin{prop}[انتقاليت]
\ollabel{prop:transitivity}
که $\Gamma \Proves !A$ او
$\{!A\} \cup \Delta \Proves !B$ وي، نو
$\Gamma \cup \Delta \Proves !B$۔
\end{prop}

source:
\begin{proof}
If $\{!A\} \cup \Delta \Proves !B$, then there is a finite subset $\Delta_0 =
\{!C_1, \dots, !C_n\} \subseteq \Delta$ such that
\begin{align*}
\{\sFmla{\False}{!B}, & \sFmla{\True}{!A}, \sFmla{\True}{!C_1},
\dots, \sFmla{\True}{!C_n}\}
\intertext{has a closed !!{tableau}. If $\Gamma \Proves !A$ then there
  are $!D_1$, \dots, $!D_m \subseteq \Gamma$ such that}
\{\sFmla{\False}{!A}, & \sFmla{\True}{!D_1},
\dots, \sFmla{\True}{!D_m}\}
\end{align*}
has a closed !!{tableau}.

target:
\begin{proof}
که $\{!A\} \cup \Delta \Proves !B$ وي، نو داسې متناهي فرعي سټ
$\Delta_0 = \{!C_1, \dots, !C_n\} \subseteq \Delta$ شته چې
\begin{align*}
\{\sFmla{\False}{!B}, & \sFmla{\True}{!A}, \sFmla{\True}{!C_1},
\dots, \sFmla{\True}{!C_n}\}
\intertext{تړلے !!{tableau} لري۔ که $\Gamma \Proves !A$ وي، نو
  داسې $!D_1$, \dots, $!D_m \in \Gamma$ شته چې}
\{\sFmla{\False}{!A}, & \sFmla{\True}{!D_1},
\dots, \sFmla{\True}{!D_m}\}
\end{align*}
تړلے !!{tableau} لري۔
\textbf{د ژباړې د نسخې سمون (OLTAB-004):} سرچينه په منځنۍ جمله
کښې د ډي-لړ يوازې وروستۍ جمله د ګاما فرعي سټ بولي؛ دلته د لړ
ټولې جملې د ګاما غړي ښودل شوې، لکه د انتقاليت تعريف چې غواړي۔

