source:
\begin{prop}
\ollabel{prop:lang-exp}
If $\Gamma$ is consistent in $\Lang L$ and $\Lang L'$ is obtained from
$\Lang L$ by adding !!a{denumerable} set of new !!{constant}s $\Obj d_0$,
$\Obj d_1$, \dots, then $\Gamma$ is consistent in~$\Lang L'$.
\end{prop}

target:
\begin{prop}
\ollabel{prop:lang-exp}
که~$\Gamma$ په~$\Lang L$ کښې سازګار وي او~$\Lang L'$ له~$\Lang L$
څخه د نوو !!{constant}s د~!!a{denumerable} سټ~$\Obj d_0$،
$\Obj d_1$، \dots په ورزياتولو ترلاسه شي، نو~$\Gamma$ په~$\Lang L'$
کښې سازګار دے۔
\end{prop}

source:
\begin{defn}[Saturated set]
A set $\Gamma$ of !!{formula}s of a language $\Lang {L}$ is
\emph{saturated} iff for each !!{formula}~$!A(x) \in \Frm[L]$ with one
free !!{variable}~$x$ there is !!a{constant}~$c \in \Lang{L}$ such
that
\iftag{prvEx}
      {$\lexists[x][!A(x)] \lif !A(c) \in \Gamma$}
      {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c) \in \Gamma$}.
\end{defn}

target:
\begin{defn}[مشبوع سټ]
د ژبې~$\Lang {L}$ د !!{formula}s يو سټ~$\Gamma$ هله او يوازې هله
\emph{مشبوع} دے چې د هر داسې !!{formula}~$!A(x) \in \Frm[L]$
دپاره چې يو ازاد !!{variable}~$x$ لري، داسې !!a{constant}
$c \in \Lang{L}$ موجود وي چې
\iftag{prvEx}
      {$\lexists[x][!A(x)] \lif !A(c) \in \Gamma$}
      {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c) \in \Gamma$}۔
\end{defn}

