\iftag{FOL}{%
\begin{defn}[Term model]
\ollabel{defn:termmodel}
Let $\Gamma^*$ be !!a{complete} and consistent,
saturated set of !!{sentence}s in a language~$\Lang L$. The \emph{term
  model}~$\Struct M(\Gamma^*)$ of $\Gamma^*$ is the !!{structure}
defined as follows:
\begin{enumerate}
\item The !!{domain}~$\Domain{M(\Gamma^*)}$ is the set of all closed
  terms of~$\Lang L$.
\item The interpretation of !!a{constant} $c$ is $c$ itself:
  $\Assign{c}{M(\Gamma^*)} = c$.
\item The !!{function}~$f$ is assigned the function which, given as
  arguments the closed terms $t_1$, \dots, $t_n$, has as value the
  closed term $f(t_1, \dots, t_n)$:
\[
\Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) = f(t_1,\dots, t_n)
\]
\item If $R$ is an $n$-place !!{predicate}, then
  \[
  \tuple{t_1, \dots,
  t_n} \in \Assign{R}{M(\Gamma^*)} \text{ iff } \Atom{R}{t_1, \dots,
    t_n} \in \Gamma^*.
  \]
\end{enumerate}
\end{defn}
}{%
\begin{defn}
\ollabel{defn:termmodel}
Suppose $\Gamma^*$ is a complete consistent set of !!{formula}s. Then we let
\[
\pAssign v(\Gamma^*)(p) = \begin{cases}
  \True & \text{if $p \in \Gamma^*$}\\
  \False & \text{if $p \notin \Gamma^*$}
  \end{cases}
\]
\end{defn}
}

target:
\iftag{FOL}{%
\begin{defn}[ترمي مدل]
\ollabel{defn:termmodel}
فرض کړئ~$\Gamma^*$ په ژبه~$\Lang L$ کښې د~!!{sentence}s يو
!!a{complete}، سازګار او مشبوع سټ دے۔ د~$\Gamma^*$
\emph{ترمي مدل}~$\Struct M(\Gamma^*)$ هغه !!{structure} ده چې په
لاندې ډول تعريفېږي:
\begin{enumerate}
\item د !!{domain}~$\Domain{M(\Gamma^*)}$ د~$\Lang L$ د ټولو
  تړلو ترمونو سټ دے۔
\item د !!a{constant}~$c$ تفسير پخپله~$c$ دے:
  $\Assign{c}{M(\Gamma^*)} = c$۔
\item !!{function}~$f$ ته هغه تابع ګومارل کېږي چې تړلي ترمونه
  $t_1$، \dots،~$t_n$ د ارګومېنټونو په توګه واخلي او تړلے
  ترم~$f(t_1, \dots, t_n)$ د قيمت په توګه ولري:
\[
\Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) = f(t_1,\dots, t_n)
\]
\item که~$R$ يو $n$-مقامي !!{predicate} وي، نو
  \[
  \tuple{t_1, \dots,
  t_n} \in \Assign{R}{M(\Gamma^*)} \text{ هله او يوازې هله چې } \Atom{R}{t_1, \dots,
    t_n} \in \Gamma^*.
  \]
\end{enumerate}
\end{defn}
}{%
\begin{defn}
\ollabel{defn:termmodel}
فرض کړئ~$\Gamma^*$ د~!!{formula}s يو بشپړ سازګار سټ دے۔ بيا ټاکو چې
\[
\pAssign v(\Gamma^*)(p) = \begin{cases}
  \True & \text{که $p \in \Gamma^*$ وي؛}\\
  \False & \text{که $p \notin \Gamma^*$ وي۔}
  \end{cases}
\]
\end{defn}
}

source:
\begin{lem} 
\ollabel{lem:val-in-termmodel} Let $\Struct M(\Gamma^*)$ be the term model
of \olref{defn:termmodel}, then $\Value{t}{M(\Gamma^*)} = t$.
\end{lem}
\begin{proof} 
 The proof is by induction on $t$, where the base case, when $t$
 is !!a{constant}, follows directly from the definition of the term
 model. For the induction step assume $t_1, \ldots, t_n$ are closed terms
 such that $\Value{t_i}{M(\Gamma^*)} = t_i$ and that $f$ is an $n$-ary
 !!{function}. Then 
\begin{align*}
\Value{f(t_1,\ldots,t_n)}{M(\Gamma^*)} &= \Assign{f}{M(\Gamma^*)}(\Value{t_1}
 {M(\Gamma^*)}, 
\ldots, \Value{t_n}{M(\Gamma^*)}) \\
&= \Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) \\
&= f(t_1,\dots, t_n),
\end{align*} 
and so by induction this holds for every closed term~$t$.
\end{proof}
}

target:
\begin{lem}
\ollabel{lem:val-in-termmodel} فرض کړئ~$\Struct M(\Gamma^*)$ د
\olref{defn:termmodel} ترمي مدل دے؛ بيا د هر تړلي ترم دپاره
$\Value{t}{M(\Gamma^*)} = t$۔
\end{lem}
\begin{proof}
 ثبوت پر~$t$ د استقرا له لارې دے۔ د بنسټ حالت، چې~$t$
 يو !!a{constant} وي، نېغ په نېغه د ترمي مدل له تعريف څخه ترلاسه
 کېږي۔ د استقرا د ګام دپاره فرض کړئ~$t_1, \ldots, t_n$ داسې تړلي
 ترمونه دي چې~$\Value{t_i}{M(\Gamma^*)} = t_i$، او~$f$ يوه
 $n$-مقامي !!{function} ده۔ بيا
\begin{align*}
\Value{f(t_1,\ldots,t_n)}{M(\Gamma^*)} &= \Assign{f}{M(\Gamma^*)}(\Value{t_1}
 {M(\Gamma^*)},
\ldots, \Value{t_n}{M(\Gamma^*)}) \\
&= \Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) \\
&= f(t_1,\dots, t_n),
\end{align*}
او نو د استقرا له مخې دا د هر تړلي ترم~$t$ دپاره سم دي۔
\end{proof}
\textbf{د ژباړې د نسخې سمون (OLCOM-008):} په سرچينه کښې د دې
ټاکنيز شرط درېيم (د لومړۍ درجې منطق د نۀ ټاکل کېدو) تش ارګومېنټ پاتې شوے و؛
دلته په څرګنده توګه ورزيات شو، څو راتلونکے شرط د هغه پر ځاے وانۀ
خيستل شي۔
}{}

