\begin{prop}
\ollabel{prop:unique-atomic}
If $!A$ is an atomic !!{formula}, then it satisfies one, and only one
of the following conditions.
\begin{enumerate}
\tagitem{prvFalse}{$!A \ident \lfalse$.}{}
\tagitem{prvTrue}{$!A \ident \ltrue$.}{}
\item $!A \ident \Atom{R}{t_1,\dots,t_n}$ where $R$ is an $n$-place
  !!{predicate}, $t_1$, \dots, $t_n$ are terms, and each of $R$,
  $t_1$, \dots, $t_n$ is uniquely determined.
\item $!A \ident \eq[t_1][t_2]$ where $t_1$ and $t_2$ are uniquely
  determined terms.
\end{enumerate}
\end{prop}

target:
\begin{prop}
\ollabel{prop:unique-atomic}
که $!A$ يو اټومي !!{formula} وي، نو له لاندې شرطونو څخه يو، او يوازې
يو، پوره کوي۔
\begin{enumerate}
\tagitem{prvFalse}{$!A \ident \lfalse$۔}{}
\tagitem{prvTrue}{$!A \ident \ltrue$۔}{}
\item $!A \ident \Atom{R}{t_1,\dots,t_n}$، چې $R$ يو $n$-ځايه
  !!{predicate}، $t_1$، \dots، $t_n$ ترمونه، او هر يو $R$،
  $t_1$، \dots، $t_n$ په يوازيني ډول ټاکل شوي دي۔
\item $!A \ident \eq[t_1][t_2]$، چې $t_1$ او $t_2$ په يوازيني ډول
  ټاکل شوي ترمونه دي۔
\end{enumerate}
\end{prop}

