\begin{prop}
\ollabel{prop:subfrm-trans}
Suppose $!B$ is a subformula of $!A$ and $!C$ is a subformula of $!B$.
Then $!C$ is a subformula of $!A$. In other words, the subformula
relation is transitive.
\end{prop}

target:
\begin{prop}
\ollabel{prop:subfrm-trans}
فرض کړئ $!B$ د $!A$ يو فرعي فارمول او $!C$ د $!B$ يو فرعي فارمول
دے۔ بيا $!C$ د $!A$ يو فرعي فارمول دے۔ په بله وينا، د فرعي فارمول
اړيکه انتقالي ده۔
\end{prop}

