\begin{defn}[تارونه]
\ollabel{defn:string}
فرض کړئ $\Lang L$ د لومړۍ درجې يوه ژبه ده۔ \emph{د~$\Lang L$ تار}
د~$\Lang L$ د سمبولونو يوه متناهي لړۍ ده۔ چې ژبه~$\Lang L$ له
چاپېريال څخه په څرګند ډول ټاکلې وي، د~$\Lang L$ تار ته به ډېر ځله
يوازې \emph{تار} وايو۔
\end{defn}

source:
\begin{ex}
For any first-order language $\Lang L$, all
$\Lang L$-!!{formula}s are $\Lang L$-strings, but not
conversely. For example, \[)(\Obj v_0\lif\lexists\] is an
$\Lang L$-string but not an $\Lang L$-!!{formula}.
\end{ex}

target:
\begin{ex}
د لومړۍ درجې د هرې ژبې $\Lang L$ دپاره ټول
$\Lang L$-!!{formula}s د~$\Lang L$ تارونه دي، خو عکس ئې سم نۀ دے۔
مثلاً \[)(\Obj v_0\lif\lexists\] د~$\Lang L$ يو تار دے، خو د~$\Lang L$
!!{formula} نۀ دے۔
\end{ex}

source:
\begin{ex}
\[
\tuple{
    \Atom{\Obj A^1_0}{\Obj v_0},
    \Atom{\Obj A^1_1}{\Obj c_1},
    (\Atom{\Obj A^1_1}{\Obj c_1} \land \Atom{\Obj A^1_0}{\Obj v_0}),
    \lexists[\Obj v_0][(\Atom{\Obj A^1_1}{\Obj c_1} \land \Atom{\Obj A^1_0}{\Obj v_0})]
}
\]
is a formation sequence of $\lexists[\Obj v_0][(\Atom{\Obj A^1_1}{\Obj
c_1} \land \Atom{\Obj A^1_0}{\Obj v_0})]$, as is
\begin{multline*}
\tuple{
    \Atom{\Obj A^1_0}{\Obj v_0},
    \Atom{\Obj A^1_1}{\Obj c_1},
    (\Atom{\Obj A^1_1}{\Obj c_1} \land \Atom{\Obj A^1_0}{\Obj v_0}),
    \Atom{\Obj A^1_1}{\Obj c_1},\\
    \lforall[\Obj v_1][\Atom{\Obj A^1_0}{\Obj v_0}],
    \lexists[\Obj v_0][(\Atom{\Obj A^1_1}{\Obj c_1} \land \Atom{\Obj A^1_0}{\Obj v_0})]
}.
\end{multline*}
%
As can be seen from the second example, formation sequences
may contain ``junk'': !!{formula}s which are redundant or do not
contribute to the construction.
\end{ex}

target:
\begin{ex}
\[
\tuple{
    \Atom{\Obj A^1_0}{\Obj v_0},
    \Atom{\Obj A^1_1}{\Obj c_1},
    (\Atom{\Obj A^1_1}{\Obj c_1} \land \Atom{\Obj A^1_0}{\Obj v_0}),
    \lexists[\Obj v_0][(\Atom{\Obj A^1_1}{\Obj c_1} \land \Atom{\Obj A^1_0}{\Obj v_0})]
}
\]
د $\lexists[\Obj v_0][(\Atom{\Obj A^1_1}{\Obj c_1} \land \Atom{\Obj
A^1_0}{\Obj v_0})]$ يوه جوړښتي لړۍ ده، او دا هم ده:
\begin{multline*}
\tuple{
    \Atom{\Obj A^1_0}{\Obj v_0},
    \Atom{\Obj A^1_1}{\Obj c_1},
    (\Atom{\Obj A^1_1}{\Obj c_1} \land \Atom{\Obj A^1_0}{\Obj v_0}),
    \Atom{\Obj A^1_1}{\Obj c_1},\\
    \lforall[\Obj v_1][\Atom{\Obj A^1_0}{\Obj v_0}],
    \lexists[\Obj v_0][(\Atom{\Obj A^1_1}{\Obj c_1} \land \Atom{\Obj A^1_0}{\Obj v_0})]
}.
\end{multline*}
%
لکه چې له دويمې بېلګې ښکاري، په جوړښتي لړيو کښې ``بې‌ګټې توکي''
هم راتلے شي: داسې !!{formula}s چې زياتي وي يا په جوړونه کښې ونډه نۀ
لري۔
\end{ex}

source:
\begin{prop}\ollabel{prop:formed}
Every !!{formula}~$!A$ in~$\Frm[L]$ has a formation sequence.
\end{prop}

target:
\begin{prop}\ollabel{prop:formed}
په~$\Frm[L]$ کښې هر !!{formula}~$!A$ يوه جوړښتي لړۍ لري۔
\end{prop}

source:
\begin{proof}
Suppose $!A$ is atomic. Then the sequence $\tuple{!A}$ is a
formation sequence for~$!A$.
%
Now suppose that $!B$ and~$!C$ have formation sequences
$\tuple{!B_0,\dotsc,!B_n}$ and $\tuple{!C_0,\dotsc,!C_m}$
respectively.
%
\begin{enumerate}
  \tagitem{prvNot}{If $!A \ident \lnot !B$,
      then $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvAnd}{If $!A \ident (!B \land !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvOr}{If $!A \ident (!B \lor !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIf}{If $!A \ident (!B \lif !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIff}{If $!A \ident (!B \liff !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvAll}{If $!A \ident \lforall[x][!B]$,
      then $\tuple{!B_0,\dotsc,!B_n,\lforall[x][!B_n]}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvEx}{If $!A \ident \lexists[x][!B]$,
      then $\tuple{!B_0,\dotsc,!B_n,\lexists[x][!B_n]}$
      is a formation sequence for~$!A$.}{}
\end{enumerate}
By the principle of induction on !!{formula}s,
every !!{formula} has a formation sequence.
\end{proof}

target:
\begin{proof}
فرض کړئ $!A$ اټومي دے۔ نو لړۍ~$\tuple{!A}$ د~$!A$ جوړښتي لړۍ ده۔
%
اوس فرض کړئ چې $!B$ او~$!C$ په ترتيب سره جوړښتي لړۍ
$\tuple{!B_0,\dotsc,!B_n}$ او $\tuple{!C_0,\dotsc,!C_m}$ لري۔
%
\begin{enumerate}
  \tagitem{prvNot}{که $!A \ident \lnot !B$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvAnd}{که $!A \ident (!B \land !C)$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvOr}{که $!A \ident (!B \lor !C)$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvIf}{که $!A \ident (!B \lif !C)$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvIff}{که $!A \ident (!B \liff !C)$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvAll}{که $!A \ident \lforall[x][!B]$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,\lforall[x][!B_n]}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvEx}{که $!A \ident \lexists[x][!B]$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,\lexists[x][!B_n]}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
\end{enumerate}
پر !!{formula}s د استقرا د اصل له مخې، هر !!{formula} يوه جوړښتي لړۍ
لري۔
\end{proof}

