\begin{prop}\ollabel{prop:sat-quant}
  Suppose $!A(x)$ only contains $x$ free, and $\Struct M$ is
  !!a{structure}. Then:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$\Sat{M}{\lexists[x][!A(x)]}$ iff $\Sat{M}{!A(x)}[s]$
      for at least one variable assignment~$s$.}{}
    \tagitem{prvAll}{$\Sat{M}{\lforall[x][!A(x)]}$ iff $\Sat{M}{!A(x)}[s]$
  for all variable assignments~$s$.}{}
\end{tagenumerate}
\end{prop}

target:
\begin{prop}\ollabel{prop:sat-quant}
  فرض کړئ $!A(x)$ يوازې~$x$ ازاد لري، او~$\Struct M$
  !!a{structure} دے۔ نو:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$\Sat{M}{\lexists[x][!A(x)]}$ هله او يوازې هله چې
      لږ تر لږه د يوې متغير ګومارنې~$s$ دپاره
      $\Sat{M}{!A(x)}[s]$۔}{}
    \tagitem{prvAll}{$\Sat{M}{\lforall[x][!A(x)]}$ هله او يوازې هله چې
      د ټولو متغير ګومارنو~$s$ دپاره $\Sat{M}{!A(x)}[s]$۔}{}
\end{tagenumerate}
\end{prop}

