\begin{defn}
\ollabel{defn:substructure}
Given !!{structure}s $\Struct M$ and $\Struct M'$ for the same
language~$\Lang L$, we say that $\Struct M$ is a \emph{sub!!{structure}}
of $\Struct M'$, and $\Struct M'$ an \emph{extension} of $\Struct M$,
written $\Struct M \substruct \Struct M'$, iff
\begin{enumerate}
\item $\Domain{M} \subseteq \Domain{M'}$,
\item For each constant $c \in \Lang L$, $\Assign{c}{M} =
    \Assign{c}{M'}$;
\item For each $n$-place !!{function} $f \in \Lang L$
  $\Assign{f}{M}(a_1, \dots, a_n) = \Assign{f}{M'}(a_1, \dots, a_n)$
  for all $a_1$, \dots, $a_n \in \Domain{M}$.
\item For each $n$-place !!{predicate} $R \in \Lang L$, $\langle
  a_1, \dots, a_n\rangle \in \Assign{R}{M}$ iff $\langle a_1, \dots,
  a_n\rangle \in \Assign{R}{M'}$ for all $a_1$, \dots, $a_n \in
  \Domain{M}$.
\end{enumerate}
\end{defn}

\begin{rem}
\ollabel{rem:substructure}
If the language contains no constant or !!{function}s, then any $N
\subseteq \Domain{M}$ determines a sub!!{structure}~$\Struct{N}$ of
$\Struct M$ with !!{domain}~$\Domain{N} = N$ by putting $\Assign{R}{N} =
\Assign{R}{M} \cap N^n$.
\end{rem}

target:
\begin{rem}
\ollabel{rem:substructure}
که ژبه ثابت يا !!{function}s ونۀ لري، نو هر
$N \subseteq \Domain{M}$ د~$\Struct M$ يو فرعي
!!{structure}~$\Struct{N}$ ټاکي چې !!{domain} ئې
$\Domain{N} = N$ دے؛ د دې دپاره $\Assign{R}{N} =
\Assign{R}{M} \cap N^n$ ږدو۔
\end{rem}

source:
\begin{thm}
\ollabel{overspill} If a set $\Gamma$ of sentences has arbitrarily
large finite models, then it has an infinite model.
\end{thm}

target:
\begin{thm}
\ollabel{overspill} که د جملو يو سټ~$\Gamma$ د هرې کچې متناهي
مدلونه ولري، نو يو نامتناهي مدل هم لري۔
\end{thm}

source:
\begin{prop}
\ollabel{inf-not-fo} 
There is no sentence $!A$ of any first-order language that is true in
!!a{structure}~$\Struct M$ if and only if the domain $\Domain{M}$ of
the !!{structure} is infinite.
\end{prop}

target:
\begin{prop}
\ollabel{inf-not-fo}
د لومړۍ درجې د هېڅ ژبې داسې جمله~$!A$ نشته چې په يوه
!!a{structure}~$\Struct M$ کښې هله او يوازې هله رښتونې وي چې د دغه
!!{structure} د تعريف ساحه~$\Domain{M}$ نامتناهي وي۔
\end{prop}

source:
\begin{proof}
If there were such a $!A$, its negation $\lnot !A$ would be true in
all and only the finite !!{structure}s, and it would therefore have
arbitrarily large finite models but it would lack an infinite model,
contradicting \olref{overspill}.
\end{proof}

target:
\begin{proof}
که داسې~$!A$ موجوده وے، نفي~$\lnot !A$ به ئې په ټولو او يوازې په
متناهي !!{structure}s کښې رښتونې وه؛ نو د هرې کچې متناهي مدلونه به
ئې لرل خو نامتناهي مدل به ئې نۀ درلود، چې دا له~\olref{overspill}
سره په ټکر کښې ده۔
\end{proof}

source:
\begin{defn}
\ollabel{defn:elem-equiv} 
Given two !!{structure}s $\Struct{M}$ and $\Struct M'$ for the same
!!{language}~$\Lang{L}$, we say that $\Struct{M}$ is \emph{elementarily
  equivalent to} $\Struct M'$, written $\Struct{M} \equiv \Struct M'$,
if and only if for every !!{sentence}~$!A$ of~$\Lang{L}$,
$\Sat{M}{!A}$ iff $\Sat{M'}{!A}$.
\end{defn}

target:
\begin{defn}
\ollabel{defn:elem-equiv}
د يوې !!{language}~$\Lang{L}$ دوه !!{structure}s $\Struct{M}$ او
$\Struct M'$ راکړل شي۔ وايو $\Struct{M}$ له~$\Struct M'$ سره
\emph{ابتدايي هم‌ارز} دے، چې $\Struct{M} \equiv \Struct M'$ ئې
ليکو، هله او يوازې هله چې د~$\Lang{L}$ د هرې !!{sentence}~$!A$
دپاره $\Sat{M}{!A}$ هله او يوازې هله چې $\Sat{M'}{!A}$ وي۔
\end{defn}

source:
\begin{defn}
\ollabel{defn:isomorphism} Given two !!{structure}s $\Struct{M}$ and
$\Struct M'$ for the same !!{language}~$\Lang L$, we say that
$\Struct{M}$ is \emph{isomorphic to}~$\Struct M'$, written $\Struct{M}
\simeq \Struct M'$, if and only if there is a function $h \colon
\Domain{M} \to \Domain{M'}$ such that:
\begin{enumerate}
\item $h$ is !!{injective}: if $h(x) =
  h(y)$ then $x = y$; 
\item $h$ is !!{surjective}: for every $y \in \Domain{M'}$ there
  is $x \in \Domain{M}$ such that $h(x) = y$;
\item \ollabel{defn:iso-const}for every !!{constant} $c$:
  $h(\Assign{c}{M}) = \Assign{c}{M'}$;
\item \ollabel{defn:iso-pred}for every $n$-place !!{predicate}~$P$:
  \[
  \tuple{a_1, \dots, a_n}\in \Assign{P}{M} \quad\text{iff}\quad
  \tuple{h(a_1), \dots, h(a_n)} \in \Assign{P}{M'};
  \]
\item \ollabel{defn:iso-func}for every $n$-place !!{function} $f$:
  \[
  h(\Assign{f}{M}(a_1, \dots, a_n)) =
  \Assign{f}{M'}(h(a_1), \dots, h(a_n)).
  \]
\end{enumerate}
\end{defn}

\begin{thm}
\ollabel{thm:isom}
If $\Struct{M} \iso \Struct M'$ then $\Struct{M} \elemequiv
\Struct{M'}$.
\end{thm}

target:
\begin{thm}
\ollabel{thm:isom}
که $\Struct{M} \iso \Struct M'$ وي، نو $\Struct{M} \elemequiv
\Struct{M'}$۔
\end{thm}

source:
If $!A$ is a sentence, the assignments~$s$ and $h \circ s$ are
irrelevant, and we have $\Sat{M}{!A}$ iff $\Sat{M'}{!A}$.
\end{proof}

target:
که $!A$ جمله وي، ګومارنې~$s$ او~$h \circ s$ بې اغېزې دي، او
$\Sat{M}{!A}$ هله او يوازې هله چې $\Sat{M'}{!A}$ لرو۔
\end{proof}

source:
\begin{prob}
Carry out the proof of (b) of \olref[mod][bas][iso]{thm:isom} in
detail. Make sure to note where each of the five properties
characterizing isomorphisms of \olref[mod][bas][iso]{defn:isomorphism}
is used.
\end{prob}

target:
\begin{prob}
د~\olref[mod][bas][iso]{thm:isom} د (b) برخې ثبوت په تفصيل بشپړ
کړئ۔ پام وکړئ چې د~\olref[mod][bas][iso]{defn:isomorphism} د
آيزومورفيزم ځانګړوونکي پنځه خاصيتونه هر يو چېرته کارول کېږي۔
\end{prob}

source:
\begin{defn}
An \emph{automorphism} of a structure $\Struct{M}$ is an isomorphism
of $\Struct{M}$ onto itself.
\end{defn}

target:
\begin{defn}
د يوه جوړښت~$\Struct{M}$ \emph{اتومورفيزم} له~$\Struct{M}$ څخه پر
خپل ځان يو آيزومورفيزم دے۔
\end{defn}

source:
\begin{prob}
Show that for any structure $\Struct{M}$, if $X$ is a definable subset
of $\Struct{M}$, and $h$ is an automorphism of $\Struct{M}$, then $X
= \Setabs{h(x)}{x \in X}$ (i.e., $X$ is fixed under $h$).
\end{prob}

target:
\begin{prob}
وښيئ چې د هر جوړښت~$\Struct{M}$ دپاره، که $X$ د~$\Struct{M}$ يو
تعريفېدونکی فرعي سټ او $h$ د~$\Struct{M}$ يو اتومورفيزم وي، نو
$X = \Setabs{h(x)}{x \in X}$ (يعنې $X$ د~$h$ لاندې ثابت پاتې کېږي)۔
\end{prob}

source:
\begin{defn}
  Given !!a{structure}~$\Struct M$, the \emph{theory} of
  $\Struct{M}$ is the set $\Theory{M}$ of !!{sentence}s
  that are true in $\Struct{M}$, i.e., $\Theory{M} =
  \Setabs{!A}{\Sat{M}{!A}}$.
\end{defn}

target:
\begin{defn}
  يو !!a{structure}~$\Struct M$ راکړل شي۔ د~$\Struct{M}$
  \emph{تيوري} د هغو !!{sentence}s سټ~$\Theory{M}$ دے چې
  په~$\Struct{M}$ کښې رښتونې وي، يعنې
  $\Theory{M} = \Setabs{!A}{\Sat{M}{!A}}$۔
\end{defn}

source:
\begin{prop}
For any $\Struct{M}$, $\Theory{M}$ is complete.
\end{prop}

target:
\begin{prop}
د هر~$\Struct{M}$ دپاره $\Theory{M}$ بشپړه ده۔
\end{prop}

source:
\begin{proof}
For any !!{sentence}~$!A$ either $\Sat{M}{!A}$ or $\Sat{M}{\lnot !A}$,
so either $!A \in \Theory{M}$ or $\lnot !A \in \Theory{M}$.
\end{proof}

target:
\begin{proof}
د هرې !!{sentence}~$!A$ دپاره يا $\Sat{M}{!A}$ وي يا
$\Sat{M}{\lnot !A}$؛ نو يا $!A \in \Theory{M}$ وي يا
$\lnot !A \in \Theory{M}$۔
\end{proof}

source:
\begin{prop}\ollabel{prop:equiv}
  If $\Struct{N} \models !A$ for every $!A \in \Theory{M}$, then
  $\Struct{M} \elemequiv \Struct{N}$.
\end{prop}

target:
\begin{prop}\ollabel{prop:equiv}
  که د هر~$!A \in \Theory{M}$ دپاره $\Struct{N} \models !A$ وي، نو
  $\Struct{M} \elemequiv \Struct{N}$۔
\end{prop}

source:
\begin{rem}\ollabel{remark:R}
  Consider $\Struct{R} = \langle\Real, <\rangle$, the !!{structure}
  whose domain is the set $\Real$ of the real numbers, in the !!{language}
  comprising only a 2-place !!{predicate} interpreted as the $<$
  relation over the reals. Clearly $\Struct{R}$ is !!{nonenumerable};
  however, since $\Theory{R}$ is obviously consistent, by the
  L\"owenheim--Skolem theorem it has !!a{enumerable} model, say
  $\Struct{S}$, and by \olref{prop:equiv}, $\Struct{R}
  \equiv \Struct{S}$. Moreover, since $\Struct{R}$ and $\Struct{S}$
  are not isomorphic, this shows that the converse of
  \olref[iso]{thm:isom} fails in general.
\end{rem}

target:
\begin{rem}\ollabel{remark:R}
  $\Struct{R} = \langle\Real, <\rangle$ وګورئ: دا هغه !!{structure}
  دے چې د تعريف ساحه ئې د حقيقي عددونو سټ~$\Real$ او !!{language} ئې
  يوازې يو دوه ځاييز !!{predicate} لري چې پر حقيقي عددونو د~$<$
  اړيکې په توګه تفسير شوے۔ څرګنده ده چې $\Struct{R}$
  !!{nonenumerable} دے؛ خو دا چې $\Theory{R}$ څرګنده سازګاره ده، د
  لوېنهايم--سکولم د قضيې له مخې !!a{enumerable} مدل لري، مثلاً
  $\Struct{S}$، او د~\olref{prop:equiv} له مخې $\Struct{R}
  \equiv \Struct{S}$۔ سربېره پر دې، دا چې $\Struct{R}$ او
  $\Struct{S}$ آيزومورف نۀ دي، ښيي چې د~\olref[iso]{thm:isom} معکوس
  په عام ډول نۀ صدق کوي۔
\end{rem}

source:
\begin{defn}
  Given two !!{structure}s $\Struct{M}$ and $\Struct{N}$, a
  \emph{partial isomorphism} from $\Struct{M}$ to $\Struct{N}$ is a
  finite partial function $p$ taking arguments in $\Domain M$ and returning
  values in $\Domain N$, which satisfies the isomorphism conditions from
  \olref[iso]{defn:isomorphism} on its domain:
  \begin{enumerate}
  \item $p$ is !!{injective};
  \item for every !!{constant}~$c$: if $p(\Assign{c}{M})$ is defined,
    then $p(\Assign{c}{M}) = \Assign{c}{N}$;
  \item for every $n$-place !!{predicate} $P$: if $a_1$, \dots, $a_n$
    are in the domain of $p$, then $\langle a_1, \dots, a_n\rangle \in
    \Assign P M$ if and only if $\langle p(a_1), \dots, p(a_n) \rangle
    \in \Assign P N$;
  \item for every $n$-place !!{function} $f$: if $a_1$, \dots, $a_n$
    are in the domain of $p$, then $p(\Assign f M (a_1, \dots,a_n))
    = \Assign f N (p(a_1), \dots, p(a_n))$.
  \end{enumerate}
  That $p$ is finite means that $\dom{p}$ is finite.
\end{defn}

\begin{defn}\ollabel{defn:partialisom}
  Two !!{structure}s $\Struct{M}$ and $\Struct{N}$, are
  \emph{partially isomorphic}, written $\Struct{M} \iso[p]
  \Struct{N}$, if and only if there is a non-empty set $I$
  of partial isomorphisms between $\Struct{M}$ and $\Struct{N}$
  satisfying the \emph{back-and-forth} property:
  \begin{enumerate}
  \item (\emph{Forth}) For every $p \in I$ and $a \in \Domain M$
    there is $q \in I$ such that $p \subseteq q$ and $a$ is
    in the domain of $q$;
  \item (\emph{Back}) For every $p \in I$ and $b \in \Domain N$
    there is $q \in I$ such that $p \subseteq q$ and $b$ is
    in the range of $q$.
  \end{enumerate}
\end{defn}

\begin{thm}\ollabel{thm:p-isom1}
  If $\Struct{M} \iso[p] \Struct{N}$ and $\Struct{M}$ and
  $\Struct{N}$ are !!{enumerable}, then $\Struct{M} \iso
  \Struct{N}$.
\end{thm}

target:
\begin{thm}\ollabel{thm:p-isom1}
  که $\Struct{M} \iso[p] \Struct{N}$ وي او $\Struct{M}$ او
  $\Struct{N}$ !!{enumerable} وي، نو $\Struct{M} \iso \Struct{N}$۔
\end{thm}

source:
\begin{prob}
  Show in detail that $p$ as defined in
  \olref[mod][bas][pis]{thm:p-isom1} is in fact an isomorphism.
\end{prob}

target:
\begin{prob}
  په تفصيل وښيئ چې په~\olref[mod][bas][pis]{thm:p-isom1} کښې تعريف
  شوے~$p$ په رښتيا يو آيزومورفيزم دے۔
\end{prob}

source:
\begin{rem}
If !!{function}s are present, the previous result is still true, but
one needs to consider the isomorphism induced by $p$ between the
sub!!{structure} of $\Struct{M}$ generated by $a_1$, \dots, $a_n$ and the
sub!!{structure} of $\Struct{N}$ generated by $b_1$, \dots, $b_n$.
\end{rem}

target:
\begin{rem}
که !!{function}s موجودې وي، مخکينۍ پايله بيا هم رښتونې ده، خو د هغه
آيزومورفيزم څېړل پکار دي چې~$p$ ئې د~$a_1$، \dots،~$a_n$ له خوا د
$\Struct{M}$ پر توليد شوي فرعي !!{structure} او د~$b_1$،
\dots،~$b_n$ له خوا د~$\Struct{N}$ پر توليد شوي فرعي !!{structure}
رامنځته کوي۔
\end{rem}

source:
\begin{prop}\ollabel{prop:qr-finite}
  Let $\Lang{L}$ be a finite purely relational !!{language}, i.e., a
  !!{language} containing finitely many !!{predicate}s and !!{constant}s,
  and no !!{function}s. Then for each $n \in \Nat$ there are
  only finitely many first-order !!{sentence}s in the !!{language}
  $\Lang{L}$ that have quantifier rank no greater than $n$, up to
  logical equivalence.
\end{prop}

\begin{proof}
  By induction on $n$.
\end{proof}

target:
\begin{proof}
  پر~$n$ په استقرا۔
\end{proof}

\begin{defn}
  يو !!a{structure}~$\Struct{M}$ راکړل شي۔ $\Domain M^{<\omega}$ د
  $\Domain{M}$ پر غړو د ټولو متناهي لړيو سټ ونيسئ۔ په~$\mathbf{a}, \mathbf{b}, \mathbf{c}, \ldots$ د غړو متناهي لړۍ ښيو۔ که
  $\mathbf{a} \in \Domain{M}^{<\omega}$ او $a \in \Domain{M}$ وي، نو
  $\mathbf{a}a$ له~$a$ سره د~$\mathbf{a}$ \emph{نښلون} ښيي۔
\end{defn}

source:
\begin{defn}
  Write $\Struct{M} \approx_n \Struct{N}$ if
  $I_n(\emptyseq,\emptyseq)$ holds of $\Struct{M}$ and
  $\Struct{N}$ (where $\emptyseq$ is the empty sequence).
\end{defn}

target:
\begin{defn}
  $\Struct{M} \approx_n \Struct{N}$ ليکو که
  $I_n(\emptyseq,\emptyseq)$ د~$\Struct{M}$ او~$\Struct{N}$ دپاره
  صدق وکړي (دلته $\emptyseq$ تشه لړۍ ده)۔
\end{defn}

source:
\begin{defn}
  A \emph{dense linear ordering without endpoints} is !!a{structure}
  $\Struct{M}$ for the !!{language} containing a single 2-place
  !!{predicate}~$<$ satisfying the following sentences:
  \begin{enumerate}
  \item $\lforall[x][\lnot x < x]$;
  \item $\lforall[x][\lforall[y][\lforall[z][(x < y \lif (y < z \lif x
    <z ))]]]$;
  \item $\lforall[x][\lforall[y][(x< y \lor \eq[x][y] \lor y < x)]]$;
  \item $\lforall[x][\lexists[y][x < y]]$;
  \item $\lforall[x][\lexists[y][y < x]]$;
  \item $\lforall[x][\lforall[y][(x < y \lif \lexists[z][(x < z \land
        z < y))]]]$.
 \end{enumerate}
\end{defn}

target:
\begin{defn}
  \emph{بې له سرحدي ټکو ګڼ خطي ترتيب} د هغې !!{language} يو !!a{structure}
  $\Struct{M}$ دے چې يوازينے دوه ځاييز !!{predicate}~$<$ لري او لاندې
  جملې پوره کوي:
  \begin{enumerate}
  \item $\lforall[x][\lnot x < x]$؛
  \item $\lforall[x][\lforall[y][\lforall[z][(x < y \lif (y < z \lif x
    <z ))]]]$؛
  \item $\lforall[x][\lforall[y][(x< y \lor \eq[x][y] \lor y < x)]]$؛
  \item $\lforall[x][\lexists[y][x < y]]$؛
  \item $\lforall[x][\lexists[y][y < x]]$؛
  \item $\lforall[x][\lforall[y][(x < y \lif \lexists[z][(x < z \land
        z < y))]]]$۔
 \end{enumerate}
\end{defn}

source:
\begin{thm}\ollabel{thm:cantorQ}
  Any two !!{enumerable} dense linear orderings without
  endpoints are isomorphic.
\end{thm}

target:
\begin{thm}\ollabel{thm:cantorQ}
  هر دوه !!{enumerable}، بې له سرحدي ټکو ګڼ خطي ترتيبونه آيزومورف دي۔
\end{thm}

source:
\begin{prob}
  Complete the proof of \olref[mod][bas][dlo]{thm:cantorQ} by
  verifying that $\PIso{I}$ satisfies the Back property.
\end{prob}

target:
\begin{prob}
  د~\olref[mod][bas][dlo]{thm:cantorQ} ثبوت په دې ښودلو بشپړ کړئ چې
  $\PIso{I}$ د شا خاصيت پوره کوي۔
