source:
\begin{prop}
  The exponentiation function $\fn{exp}(x, y) = x^y$ is primitive recursive.
\end{prop}

target:
\begin{prop}
  د توان تابع~$\fn{exp}(x, y) = x^y$ بنسټيزه بازګشتي ده۔
\end{prop}

source:
\begin{proof}
  We can define $\fn{exp}$ primitive recursively as
  \begin{align*}
    \fn{exp}(x, 0) & = 1\\
    \fn{exp}(x, y+1) & = \Mult(x, \fn{exp}(x,y)).
    \intertext{Strictly speaking, this is not a recursive definition
      from primitive recursive functions. Officially, though, we
      have:}
    \fn{exp}(x, 0) & = f(x)\\
    \fn{exp}(x, y+1) & = g(x, y, \fn{exp}(x,y)).
    \intertext{where}
    f(x) & = \Succ(\Zero(x)) = 1\\
    g(x, y, z) & = \Mult(\Proj{3}{0}(x, y, z), \Proj{3}{2}(x, y, z)) = x \cdot z
  \end{align*}
  and so $f$ and $g$ are defined from primitive recursive functions by
  composition.
\end{proof}

target:
\begin{proof}
  $\fn{exp}$ په بنسټيز بازګښت داسې تعريفولے شو:
  \begin{align*}
    \fn{exp}(x, 0) & = 1\\
    \fn{exp}(x, y+1) & = \Mult(x, \fn{exp}(x,y)).
    \intertext{په کره توګه دا لا له بنسټيزو بازګشتي تابعو څخه يو بازګشتي تعريف نۀ دے۔ خو رسمي بڼه ئې داسې ده:}
    \fn{exp}(x, 0) & = f(x)\\
    \fn{exp}(x, y+1) & = g(x, y, \fn{exp}(x,y)).
    \intertext{چې پکښې}
    f(x) & = \Succ(\Zero(x)) = 1\\
    g(x, y, z) & = \Mult(\Proj{3}{0}(x, y, z), \Proj{3}{2}(x, y, z)) = x \cdot z
  \end{align*}
  او په دې ډول~$f$ او~$g$ له بنسټيزو بازګشتي تابعو څخه په ترکيب تعريف شوې دي۔
\end{proof}

