\begin{prop}
  The predecessor function $\fn{pred}(y)$ defined by
  \[
  \fn{pred}(y) = \begin{cases}
    0 & \text{if $y=0$}\\
    y-1 & \text{otherwise}
  \end{cases}
  \]
  is primitive recursive.
\end{prop}

target:
\begin{prop}
  مخکينۍ تابع~$\fn{pred}(y)$ چې داسې تعريف شوې ده،
  \[
  \fn{pred}(y) = \begin{cases}
    0 & \text{که $y=0$ وي}\\
    y-1 & \text{که نۀ}
  \end{cases}
  \]
  بنسټيزه بازګشتي ده۔
\end{prop}

source:
\begin{proof}
 Note that 
 \begin{align*}
   \fn{pred}(0) & = 0 \text{ and}\\
   \fn{pred}(y+1) & = y.
 \end{align*}
 This is almost a primitive recursive definition.  It does not,
 strictly speaking, fit into the pattern of definition by primitive
 recursion, since that pattern requires at least one extra
 argument~$x$. It is also odd in that it does not actually use
 $\fn{pred}(y)$ in the definition of $\fn{pred}(y+1)$. But we can
 first define $\fn{pred}'(x, y)$ by
 \begin{align*}
   \fn{pred}'(x, 0) & = \Zero(x) = 0,\\
   \fn{pred}'(x, y+1) & = \Proj{3}{1}(x, y, \fn{pred'}(x, y)) = y.
 \end{align*}
and then define $\fn{pred}$ from it by composition, e.g., as
$\fn{pred}(x) = \fn{pred}'(\Zero(x), \Proj{1}{0}(x))$.
\end{proof}

target:
\begin{proof}
 پام وکړئ چې
 \begin{align*}
   \fn{pred}(0) & = 0 \text{ او}\\
   \fn{pred}(y+1) & = y.
 \end{align*}
 دا نژدې يو بنسټيز بازګشتي تعريف دے۔ په کره توګه د بنسټيز بازګښت د تعريف له نمونې سره ځکه نۀ سمېږي چې هغه نمونه لږ تر لږه يو زيات آرګومېنټ~$x$ غواړي۔ دا په دې لحاظ هم نابلده ده چې د $\fn{pred}(y+1)$ په تعريف کښې په رښتيا~$\fn{pred}(y)$ نۀ کاروي۔ خو لومړے~$\fn{pred}'(x, y)$ داسې تعريفولے شو:
 \begin{align*}
   \fn{pred}'(x, 0) & = \Zero(x) = 0,\\
   \fn{pred}'(x, y+1) & = \Proj{3}{1}(x, y, \fn{pred'}(x, y)) = y.
 \end{align*}
او بيا~$\fn{pred}$ ترې په ترکيب تعريفولے شو، مثلاً داسې:
$\fn{pred}(x) = \fn{pred}'(\Zero(x), \Proj{1}{0}(x))$۔
\end{proof}

source:
\begin{prop}
  The factorial function $\fn{fac}(x) = \fact{x} = 1 \cdot 2 \cdot 3
  \cdot \dots \cdot x$ is primitive recursive.
\end{prop}

target:
\begin{prop}
  د فاکتوريل تابع~$\fn{fac}(x) = \fact{x} = 1 \cdot 2 \cdot 3 \cdot \dots \cdot x$ بنسټيزه بازګشتي ده۔
\end{prop}

source:
\begin{proof}
  The obvious primitive recursive definition is
  \begin{align*}
    \fn{fac}(0) &= 1\\
    \fn{fac}(y+1) & = \fn{fac}(y) \cdot (y+1).
    \intertext{Officially, we have to first define a two-place function $h$}
    h(x, 0) & = \fn{const}_1(x)\\
    h(x, y+1) & = g(x, y, h(x, y))
    \intertext{where $g(x, y, z) = \Mult(\Proj{3}{2}(x, y, z),
      \Succ(\Proj{3}{1}(x, y, z)))$ and then let}
    \fn{fac}(y) & = h(\Proj{1}{0}(y), \Proj{1}{0}(y)) = h(y,y).
  \end{align*}
  From now on we'll be a bit more laissez-faire and not give the official
  definitions by composition and primitive recursion.
\end{proof}

target:
\begin{proof}
  څرګند بنسټيز بازګشتي تعريف دا دے:
  \begin{align*}
    \fn{fac}(0) &= 1\\
    \fn{fac}(y+1) & = \fn{fac}(y) \cdot (y+1).
    \intertext{په رسمي ډول لومړے دوه ځاييزه تابع~$h$ داسې تعريفوو:}
    h(x, 0) & = \fn{const}_1(x)\\
    h(x, y+1) & = g(x, y, h(x, y))
    \intertext{چې پکښې $g(x, y, z) = \Mult(\Proj{3}{2}(x, y, z), \Succ(\Proj{3}{1}(x, y, z)))$ ده؛ بيا ږدو چې}
    \fn{fac}(y) & = h(\Proj{1}{0}(y), \Proj{1}{0}(y)) = h(y,y).
  \end{align*}
  له دې وروسته به لږ کم رسمي واوسو او هر ځل به د ترکيب او بنسټيز بازګښت بشپړ رسمي تعريفونه نۀ ورکوو۔
\end{proof}

source:
\begin{prop}
  Truncated subtraction, $x \tsub y$, defined by
  \[
  x \tsub y = \begin{cases}
