\begin{prop}
  The function $\fn{append}(s,a)$, which returns the result of appending $a$ to
  the sequence $s$, is primitive recursive.
\end{prop}

target:
\begin{prop}
  تابع~$\fn{append}(s,a)$، چې د لړۍ~$s$ په پاے کښې د~$a$ د ورزياتولو پايله راګرځوي، بنسټيزه بازګشتي ده۔
\end{prop}

source:
\begin{proof}
  $\fn{append}$ can be defined by:
  \[
  \fn{append}(s,a) =
  \begin{cases}
    2^{a+1} & \text{if $s = 0$ or $s = 1$} \\
    s \cdot p_{\len{s}}^{a+1} & \text{otherwise.}
  \end{cases}
  \]
\end{proof}

target:
\begin{proof}
  $\fn{append}$ داسې تعريفېدے شي:
  \[
  \fn{append}(s,a) =
  \begin{cases}
    2^{a+1} & \text{که $s = 0$ يا $s = 1$ وي} \\
    s \cdot p_{\len{s}}^{a+1} & \text{که نۀ۔}
  \end{cases}
  \]
\end{proof}

source:
\begin{prop}
  The function $\fn{element}(s,i)$, which returns the $i$th element of $s$
  (where the initial element is called the $0$th), or $0$ if $i$ is
  greater than or equal to the length of $s$, is primitive recursive.
\end{prop}

target:
\begin{prop}
  تابع~$\fn{element}(s,i)$، چې د~$s$ $i$م غړے راګرځوي (لومړني غړي ته~$0$م وايي)، او که~$i$ د~$s$ له اوږدوالي څخه لوے يا ورسره برابر وي نو~$0$ راګرځوي، بنسټيزه بازګشتي ده۔
\end{prop}

source:
\begin{proof}
Note that $a$ is the $i$th element of~$s$ iff $p_i^{a+1}$ is
the largest power of~$p_i$ that divides~$s$, i.e., $p_i^{a+1} \mid s$
but $p_i^{a+2} \nmid s$. So:
  \[
  \fn{element}(s,i) =
  \begin{cases}
    0 & \mbox{if $i \geq \len{s}$} \\
    \bmin{a < s}{(p_i^{a+2} \nmid s)} & \text{otherwise.}
  \end{cases}
  \]
\end{proof}

target:
\begin{proof}
پام وکړئ چې~$a$ هله او يوازې هله د~$s$ $i$م غړے دے چې $p_i^{a+1}$ د~$p_i$ تر ټولو لوے توان وي چې~$s$ وېشي؛ يعنې $p_i^{a+1} \mid s$ وي خو~$p_i^{a+2} \nmid s$ وي۔ نو:
  \[
  \fn{element}(s,i) =
  \begin{cases}
    0 & \mbox{که $i \geq \len{s}$ وي} \\
    \bmin{a < s}{(p_i^{a+2} \nmid s)} & \text{که نۀ۔}
  \end{cases}
  \]
\end{proof}

source:
\begin{prop}
The function $\fn{concat}(s,t)$, which concatenates two
sequences, is primitive recursive.
\end{prop}

target:
\begin{prop}
تابع~$\fn{concat}(s,t)$، چې دوه لړۍ سره نښلوي، بنسټيزه بازګشتي ده۔
\end{prop}

\begin{proof}
  داسې تابع~$\fn{concat}$ غواړو چې دا خاصيت ولري:
  \[
    \fn{concat}(\tuple{a_0, \dots, a_k}, \tuple{b_0, \dots, b_l}) = \tuple{a_0, \dots, a_k, b_0, \dots, b_l}.
  \]
  مرستندويه تابع~$\fn{hconcat}(s,t,n)$ کاروو چې د~$t$ لومړۍ~$n$ نښې له~$s$ سره نښلوي۔ دا تابع په بنسټيز بازګښت داسې تعريفېدے شي:
  \begin{align*}
    \fn{hconcat}(s,t,0) & = s\\
    \fn{hconcat}(s,t,n+1) & = \fn{append}(\fn{hconcat}(s,t,n),(t)_n)
    \intertext{بيا~$\fn{concat}$ داسې تعريفولے شو:}
    \fn{concat}(s,t) & = \fn{hconcat}(s,t,\len{t}).
  \end{align*}
\end{proof}

\begin{prob}
وښيئ چې داسې بنسټيزه بازګشتي تابع~$\fn{sconcat}(s)$ شته چې دا خاصيت ولري:
\[
\fn{sconcat}(\tuple{s_0, \dots, s_k}) = s_0 \concat \dots \concat s_k.
\]
\end{prob}

