source:
\begin{prop}
  \ollabel{prop:subtreeseq}
  The function $\fn{SubtreeSeq}(t)$, which returns the code of a
  sequence the elements of which are the codes of all subtrees of the
  tree with code~$t$, is primitive recursive.
\end{prop}

target:
\begin{prop}
  \ollabel{prop:subtreeseq}
  تابع~$\fn{SubtreeSeq}(t)$، چې د داسې لړۍ کوډ راګرځوي چې غړي ئې د $t$ کوډ لرونکې ونې د ټولو فرعي ونو کوډونه دي، بنسټيزه بازګشتي ده۔
\end{prop}

\begin{proof}
  لومړے پام وکړئ چې~$\fn{ISubtrees}(t) = \fn{subseq}(t, 1, (t)_0)$ بنسټيزه بازګشتي ده او د ونې~$t$ د سمدستي فرعي ونو کوډونه راګرځوي۔ اوس مرستندويه تابع~$\fn{hSubtreeSeq}(t,n)$ داسې تعريفوو چې د ټولو هغو فرعي ونو لړۍ محاسبه کړي چې ريښې ئې د~$t$ له ريښې څخه تر ټولو زيات~$n$ څنډې لرې وي۔ د~$t$ د هغو فرعي ونو لړۍ چې له ريښې څخه تر ټولو زيات~$0$ څنډې لرې دي---يعنې پخپله د~$t$ په ريښه پيلېږي---يوازې له~$t$ څخه جوړه لړۍ ده۔ د~$n+1$ تر کچې د ټولو فرعي ونو د لړۍ د ترلاسه کولو دپاره، د~$n$ تر کچې شته فرعي ونې د هغو ټولو سمدستي فرعي ونو له لړۍ سره نښلوو چې د~$n$ تر کچې له فرعي ونو راځي۔
  \textbf{د ژباړې د نسخې سمون (OLCMP-013):} سرچينې مرستندويه تابع له ريښې څخه په کټ مټ ټاکلي واټن د فرعي ونو لړۍ بلله، خو لاندې بازګشتي ګام مخکينۍ لړۍ هم ساتي او تر ټاکلي واټن پورې ټولې کچې راټولوي۔ دلته تشريح د هماغې معادلې له مجموعي چلند سره برابره شوې ده۔
  د ټولو د لست د ترلاسه کولو دپاره پام وکړئ: که~$f(x)$ يوه بنسټيزه بازګشتي تابع وي چې د لړيو کوډونه راګرځوي، نو د غړو د مثبت شمېر دپاره تابع~$g_f(s,k)=f((s)_0) \concat \dots \concat f((s)_{k-1})$ هم بنسټيزه بازګشتي ده؛ د صفر غړو نښلون تشه لړۍ نيسو:
    \begin{align*}
      g(s, 0) & = \emptyseq\\
      g(s, k+1) & = g(s, k) \concat f((s)_k)
    \end{align*}
    مثلاً، که~$s$ د ونو يوه لړۍ وي، نو $h(s) = g_{\fn{ISubtrees}}(s, \len{s})$ د~$s$ د غړو د ټولو سمدستي فرعي ونو لړۍ راکوي۔
    \textbf{د ژباړې د نسخې سمون (OLCMP-014):} سرچينې مرستندويه نښلون د صفرم غړي په تابع پيل کاوه او بيا ئې تر اوږدوالي پورې ټول‌شموله شاخص غځاوه؛ په دې سره ئې د لړۍ له وروستي قانوني شاخص وروسته يو زيات غړے لوسته۔ دلته پاراميټر د لومړيو غړو شمېر دے: صفر تش نښلون ورکوي او هر راتلونکی ګام سملاسي ورپسې قانوني غړے زياتوي۔
    له دې څخه~$\fn{hSubtreeSeq}$ داسې تعريفولے شو:
    \begin{align*}
      \fn{hSubtreeSeq}(t, 0) & = \tuple{t} \\
      \fn{hSubtreeSeq}(t, n+1) & = \fn{hSubtreeSeq}(t, n) \concat h(\fn{hSubtreeSeq}(t, n)).
    \end{align*}
    د~$t$ په کوډ شوې ونه کښې د فرعي ونو تر ټولو لوړه کچه، يعنې د ريښې او يوې پاڼه غوټې تر منځ تر ټولو لوے واټن، د کوډ~$t$ له مخې محدوده ده۔ نو د~$t$ په کوډ شوې ونه کښې د ټولو فرعي ونو د کوډونو لړۍ~$\fn{hSubtreeSeq}(t, t)$ ورکوي۔
\end{proof}

source:
\begin{prob}
  The definition of $\fn{hSubtreeSeq}$ in the proof of
  \olref[cmp][rec][tre]{prop:subtreeseq} in general includes
  repetitions. Give an alternative definition which guarantees that
  the code of a subtree occurs only once in the resulting list.
\end{prob}

target:
\begin{prob}
  د~\olref[cmp][rec][tre]{prop:subtreeseq} په ثبوت کښې د $\fn{hSubtreeSeq}$ تعريف په عمومي ډول تکرارونه راولي۔ يو داسې بل تعريف ورکړئ چې ضمانت وکړي د يوې فرعي ونې کوډ په پايله لست کښې يوازې يو ځل راځي۔
\end{prob}

د جوړو او لړيو په کارولو د بنسټيز بازګښت لا نابلده (او ګټورې) بڼې توجيه کولے شو۔ مثلاً ډېر وخت دوه تابعې يوځاے تعريفول ګټور وي، لکه په لاندې تعريف کښې:
\begin{align*}
h_0(\vec x, 0) & = f_0(\vec x) \\
h_1(\vec x, 0) & = f_1(\vec x) \\
h_0(\vec x, y+1) & = g_0(\vec x, y, h_0(\vec x, y), h_1(\vec x, y)) \\
h_1(\vec x, y+1) & = g_1(\vec x, y, h_0(\vec x, y), h_1(\vec x, y))
\end{align*}
دا د \emph{هممهاله بازګښت} يوه بېلګه ده۔ د تابعو د تعريف بله ګټوره لار دا ده چې د~$h(\vec x, y+1)$ ارزښت د ټولو ارزښتونو $h(\vec x, 0)$، \dots،~$h(\vec x, y)$ له مخې ورکړو، لکه په لاندې تعريف کښې:
\begin{align*}
h(\vec x, 0) & = f(\vec x) \\
h(\vec x, y+1) & = g(\vec x, y, \tuple{h(\vec x, 0), \dots, h(\vec x, y)}).
\end{align*}
لاندې چوکاټ دا مفکوره لا لنډه بيانوي:
\[
h(\vec x, y) = g(\vec x, y, \tuple{h(\vec x, 0), \dots, h(\vec x, y-1)})
\]
په دې پوهېدو سره چې کله~$y$، $0$ وي، د~$g$ وروستے آرګومېنټ يوازې تشه لړۍ وي۔ په دواړو بڼو کښې مفکوره دا ده چې د «راتلونکي ګام» د محاسبې پر مهال تابع~$h$ تر دې ځايه د محاسبه شوو ارزښتونو ټوله لړۍ کارولے شي۔ دې ته \emph{د ارزښتونو د بهير بازګښت} وايي۔ د يوې ځانګړې بېلګې دپاره لاندې ډول تعريف توجيه کولے شي:
\begin{align*}
h(\vec x, y) & = \begin{cases}
  g(\vec x, y, h(\vec x, k(\vec x, y))) & \text{که $k(\vec x, y) < y$ وي} \\
  f(\vec x) & \text{که نۀ}
\end{cases}
\end{align*}
په بله وينا، په~$y$ د~$h$ ارزښت د~$h$ د هر مخکيني ارزښت له مخې محاسبه کېدے شي، او هغه مخکينی ارزښت~$k$ ورکوي۔

source:
\begin{prob}
  Define the remainder function $r(x,y)$ by course-of-values
  recursion. (If $x$, $y$ are natural numbers and $y > 0$, $r(x,y)$ is
  the number less than~$y$ such that $x = z\times y + r(x,y)$ for
  some~$z$. For definiteness, let's say that if $y=0$, $r(x,0) = 0$.)
\end{prob}

target:
\begin{prob}
  د پاتې شوني تابع~$r(x,y)$ د ارزښتونو د بهير په بازګښت تعريف کړئ۔ (که~$x$ او~$y$ طبيعي عددونه او~$y > 0$ وي، نو~$r(x,y)$ له~$y$ څخه هغه کوچنے عدد دے چې د کوم~$z$ دپاره $x = z\times y + r(x,y)$ وي۔ د کره‌والي دپاره وايو که~$y=0$ وي، نو~$r(x,0) = 0$۔)
\end{prob}

بايد په دې فکر وکړئ چې دا تابعې په عادي بنسټيز بازګښت څنګه ترلاسه کېږي۔ د بنسټيز بازګښت يوه وروستۍ بڼه په دې لحاظ لا انعطاف منونکې ده چې د لارې په اوږدو کښې د \emph{پاراميټرونو} (اړخيزو ارزښتونو) بدلولو اجازه ورکوي:
\begin{align*}
h(\vec x, 0) & = f(\vec x) \\
h(\vec x, y+1) & = g(\vec x, y, h(k(\vec x), y))
\end{align*}
دا هم په عادي بنسټيز بازګښت تقليدېدے شي۔ (دا کول ستونزمن دي۔ د يوې لارښوونې دپاره، محاسبه په لاس له پاے څخه بېرته پرانيزئ۔)

د هغو محاسبه کېدونکو تابعو لا څرګندې بېلګې هم ورکولے شو چې بنسټيزې بازګشتي نۀ دي۔ مثلاً نښه~$g^n(x)$ دې~$g(g(\dots g(x)))$ وښيي، چې ټولې~$n$ دانې~$g$ګانې لري؛ او د تابعو لړۍ~$g_0,g_1,\dots$ داسې تعريف کړئ:
\begin{eqnarray*}
g_0(x) & = & x+1 \\
g_{n + 1}(x) & = & g_n^x(x)
\end{eqnarray*}
تاسو ارزولے شئ چې هره تابع~$g_n$ بنسټيزه بازګشتي ده۔ هره ورپسې تابع له مخکينۍ څخه ډېره چټکه لوېږي؛ $g_1(x)$ له~$2x$ سره برابره ده، $g_2(x)$ له~$2^x \cdot x$ سره برابره ده، او~$g_3(x)$ نژدې د~$x$ دانو~$2$ګانو د تواني برج په شان لوېږي۔ د اکرمن--پېټر تابع په اصل کښې همدا تابع~$G(x) = g_x(x)$ ده، او ښودل کېدے شي چې دا له هرې بنسټيزې بازګشتي تابع څخه چټکه لوېږي۔

