source:
\begin{prob}
\emph{Equality:} Design a Turing machine to compute the following function:
\[
\fn{equality}(n,m) = 
\begin{cases}
  \text{1} & \text{if~$n = m$} \\
  \text{0} & \text{if~$n \neq m$}
\end{cases}
\]
where~$n$ and~$m \in \PosInt$.
\end{prob}

target:
\begin{prob}
\emph{مساوات:} داسې ټيورينګ ماشين طرح کړئ چې لاندې تابع محاسبه کړي:
\[
\fn{equality}(n,m) =
\begin{cases}
  \text{1} & \text{که~$n = m$ وي} \\
  \text{0} & \text{که~$n \neq m$ وي}
\end{cases}
\]
چې پکښې~$n$ او~$m \in \PosInt$ دي۔
\end{prob}

