source:
\begin{prop}
The following relations are primitive recursive:
\begin{enumerate}
\item $\fn{Fn}(x, n)$ iff $x$ is the code of $\Obj f^n_i$ for
  some~$i$, i.e., $x$ is the code of an $n$-ary !!{function}.
\item $\fn{Pred}(x, n)$ iff $x$ is the code of $\Obj P^n_i$ for
  some~$i$ or $x$ is the code of $\eq$ and $n = 2$, i.e., $x$ is the
  code of an $n$-ary !!{predicate}.
\end{enumerate}
\end{prop}

target:
\begin{prop}
لاندې اړيکې بنسټيزې بازګشتي دي:
\begin{enumerate}
\item $\fn{Fn}(x, n)$ هله صدق کوي چې $x$ د کوم~$i$ دپاره د
  $\Obj f^n_i$ کوډ وي؛ يعنې $x$ د يوې $n$-ځايه !!{function} کوډ وي۔
\item $\fn{Pred}(x, n)$ هله صدق کوي چې $x$ د کوم~$i$ دپاره د
  $\Obj P^n_i$ کوډ وي، يا $x$ د~$\eq$ کوډ او $n = 2$ وي؛ يعنې $x$
  د يوه $n$-ځايه !!{predicate} کوډ وي۔
\end{enumerate}
\end{prop}

source:
\begin{defn}
If $s_0, \dots, s_{n-1}$ is a sequence of symbols, its \emph{G\"odel
  number} is $\tuple{\scode{s_0}, \dots, \scode{s_{n-1}}}$.
\end{defn}

target:
\begin{defn}
که $s_0, \dots, s_{n-1}$ د سمبولونو يوه لړۍ وي، د هغې
\emph{ګوډل شمېره} $\tuple{\scode{s_0}, \dots, \scode{s_{n-1}}}$ ده۔
\end{defn}

\begin{explain}
پام وکړئ چې \emph{کوډونه} او \emph{ګوډل شمېرې} بېل څيزونه دي۔ د
بېلګې په توګه متغير~$\Obj v_5$ کوډ~$\scode{\Obj v_5} = \tuple{1, 5}
= 2^2\cdot 3^6$ لري۔ خو که متغير~$\Obj v_5$ د يوه ترم په توګه
وګڼو، دا د سمبولونو يوه لړۍ (د اوږدوالي~$1$) هم ده۔ د
\emph{ترم}~$\Obj v_5$ \emph{ګوډل شمېره}~$\Gn{\Obj v_5}$ دا ده:
$\tuple{\scode{\Obj v_5}} = 2^{\scode{\Obj v_5} + 1} =
2^{2^2\cdot 3^6 + 1}$۔
\end{explain}

source:
\begin{prop}
\ollabel{prop:term-primrec}
The relations $\fn{Term}(x)$ and $\fn{ClTerm}(x)$ which hold iff $x$
is the G\"odel number of a term or a closed term, respectively, are
primitive recursive.
\end{prop}

target:
\begin{prop}
\ollabel{prop:term-primrec}
هغه اړيکې $\fn{Term}(x)$ او $\fn{ClTerm}(x)$ چې په ترتيب هله صدق کوي
چې $x$ د يوه ترم يا تړلي ترم ګوډل شمېره وي، بنسټيزې بازګشتي دي۔
\end{prop}

source:
\begin{prob}
Show that the function $\fn{flatten}(z)$, which turns the sequence
$\tuple{\Gn{t_1}, \dots, \Gn{t_n}}$ into $\Gn{t_1, \dots, t_n}$, is
primitive recursive.
\end{prob}

target:
\begin{prob}
وښيئ چې تابع $\fn{flatten}(z)$، چې لړۍ
$\tuple{\Gn{t_1}, \dots, \Gn{t_n}}$ په $\Gn{t_1, \dots, t_n}$
بدلوي، بنسټيزه بازګشتي ده۔
\end{prob}

source:
\begin{prop}\ollabel{prop:num-primrec}
  The function $\fn{num}(n) = \Gn{\num{n}}$ is primitive recursive.
\end{prop}

target:
\begin{prop}\ollabel{prop:num-primrec}
  تابع $\fn{num}(n) = \Gn{\num{n}}$ بنسټيزه بازګشتي ده۔
\end{prop}

source:
\begin{proof}
  We define $\fn{num}(n)$ by primitive recursion:
  \begin{align*}
    \fn{num}(0) & = \Gn{\Obj 0}\\
    \fn{num}(n+1) & = \Gn{\prime(} \concat \fn{num}(n) \concat \Gn{)}.
  \end{align*}
\end{proof}

target:
\begin{proof}
