\begin{defn}
\ollabel{defn:representable-fn}
  A function $f(x_0,\ldots,x_k)$ from the natural numbers to
  the natural numbers is said to be {\em representable in $\Th{Q}$} if
  there is a formula $!A_f(x_0,\dots,x_k,y)$ such that whenever
  $f(n_0,\dots,n_k) = m$, $\Th{Q}$ proves
\begin{enumerate}
\item\ollabel{defn:rep:a} $!A_f(\num{n_0}, \dots, \num{n_k}, \num{m})$
\item\ollabel{defn:rep:b} $\lforall[y][(!A_f(\num{n_0}, \dots,
\num{n_k}, y) \lif \num{m} = y)]$.
\end{enumerate}
\end{defn}

target:
\begin{defn}
\ollabel{defn:representable-fn}
  له طبيعي عددونو څخه طبيعي عددونو ته تابعه
  $f(x_0,\ldots,x_k)$ هله \emph{په~$\Th{Q}$ کښې تمثيلېدونکې}
  بلل کېږي چې داسې فارمول~$!A_f(x_0,\dots,x_k,y)$ وي چې هر
  کله~$f(n_0,\dots,n_k) = m$ وي، $\Th{Q}$ لاندې دواړه ثابت کړي:
\begin{enumerate}
\item\ollabel{defn:rep:a} $!A_f(\num{n_0}, \dots, \num{n_k}, \num{m})$
\item\ollabel{defn:rep:b} $\lforall[y][(!A_f(\num{n_0}, \dots,
\num{n_k}, y) \lif \num{m} = y)]$۔
\end{enumerate}
\end{defn}

source:
\begin{thm}
\ollabel{thm:representable-iff-comp}
A function is representable in $\Th{Q}$ if and only if it is computable.
\end{thm}

target:
\begin{thm}
\ollabel{thm:representable-iff-comp}
يوه تابعه په~$\Th{Q}$ کښې هله او يوازې هله تمثيلېدونکې ده چې
محاسبه کېدونکې وي۔
\end{thm}

source:
\begin{lem}
Every function that is representable in $\Th{Q}$ is computable.
\end{lem}

target:
\begin{lem}
هره هغه تابعه چې په~$\Th{Q}$ کښې تمثيلېدونکې وي، محاسبه کېدونکې
ده۔
\end{lem}

source:
\begin{lem}
\ollabel{lem:beta}
There is a function $\beta(d,i)$ such that for every sequence $a_0$,
\dots,~$a_n$ there is a number~$d$, such that for every $i \le n$,
$\beta(d,i) = a_i$. Moreover, $\beta$ can be defined from the basic
functions using just composition and regular minimization.
\end{lem}

target:
\begin{lem}
\ollabel{lem:beta}
داسې تابعه~$\beta(d,i)$ شته چې د هرې لړۍ $a_0$، \dots،~$a_n$
دپاره داسې عدد~$d$ شته چې د هر~$i \le n$ دپاره
$\beta(d,i) = a_i$ وي۔ سربېره پر دې،~$\beta$ له بنسټيزو تابعو څخه
يوازې د ترکيب او منظم اقل موندلو په کارولو تعريفېدے شي۔
\end{lem}

source:
\begin{defn}
Two natural numbers $a$ and $b$ are \emph{relatively prime} iff their
greatest common divisor is~$1$; in other words, they have no other
divisors in common.
\end{defn}

target:
\begin{defn}
دوه طبيعي عددونه~$a$ او~$b$ هله \emph{خپلمنځي اول} دي چې ستر
ګډ مقسوم‌عليه ئې~$1$ وي؛ په بله وينا، له دې پرته بل ګډ مقسوم‌عليه
نۀ لري۔
\end{defn}

source:
\begin{defn}
Natural numbers $a$ and $b$ are \emph{congruent modulo~$c$},
$a \equiv b \mod c$, iff $c \mid (a-b)$, i.e., $a$ and $b$ have the
same remainder when divided by~$c$.
\end{defn}

target:
\begin{defn}
طبيعي عددونه~$a$ او~$b$ \emph{د~$c$ په مودولو سره مطابق} دي،
$a \equiv b \mod c$، هله چې~$c \mid (a-b)$؛ يعنې کله چې پر~$c$
ووېشل شي،~$a$ او~$b$ يو شان پاتې شونې لري۔
\end{defn}

source:
Here is Sunzi's Theorem:
\begin{thm}
Suppose $x_0$, \dots,~$x_n$ are (pairwise) relatively prime. Let
$y_0$, \dots,~$y_n$ be any numbers. Then there is a number $z$ such that
\begin{align*}
z & \equiv y_0 \mod x_0 \\
z & \equiv y_1 \mod x_1 \\
& \vdots  \\
z & \equiv y_n \mod x_n.
\end{align*}
\end{thm}

target:
دا د سونزي قضيه ده:
\begin{thm}
فرض کړئ $x_0$، \dots،~$x_n$ (جوړه په جوړه) خپلمنځي اول دي۔
$y_0$، \dots،~$y_n$ هر عددونه وي۔ بيا داسې عدد~$z$ شته چې
\begin{align*}
z & \equiv y_0 \mod x_0 \\
z & \equiv y_1 \mod x_1 \\
& \vdots  \\
z & \equiv y_n \mod x_n.
\end{align*}
\end{thm}

source:
\begin{prob}
  Show that the relations $x < y$, $x \mid y$, and the
  function~$\fn{rem}(x,y)$ can be defined without primitive recursion.
  You may use $0$, successor, plus, times, $\Char{=}$, projections,
  and bounded minimization and quantification.
\end{prob}

target:
\begin{prob}
  وښيئ چې اړيکې~$x < y$، $x \mid y$، او تابعه
  $\fn{rem}(x,y)$ له بنسټيز بازګښت پرته تعريفېدے شي۔ $0$، تالي،
  جمع، ضرب،~$\Char{=}$، پروجکشنونه، او محدوده کمينه‌موندنه او کمیت
  ايښودنه کارولے شئ۔
\end{prob}

source:
\begin{lem}
\ollabel{lem:prim-rec}
If $h$ can be defined from $f$ and $g$ using primitive recursion, it
can be defined from $f$, $g$, the functions $\Zero$, $\Succ$,
$\Proj{n}{i}$, $\Add$, $\Mult$, $\Char{=}$, using composition and
regular minimization.
\end{lem}

target:
\begin{lem}
\ollabel{lem:prim-rec}
که~$h$ له~$f$ او~$g$ څخه په بنسټيز بازګښت تعريفېدے شي، نو له~$f$،
$g$، تابعو~$\Zero$، $\Succ$، $\Proj{n}{i}$، $\Add$، $\Mult$،
$\Char{=}$ څخه د ترکيب او منظم اقل موندلو په کارولو تعريفېدے شي۔
\end{lem}

source:
\begin{prop}
\ollabel{prop:rep-zero}
The zero function $\Zero(x) = 0$ is represented in~$\Th{Q}$ by
$!A_{\Zero}(x,y) \ident \eq[y][\Obj 0]$.
\end{prop}

target:
