target:
\begin{thm}
\ollabel{thm:first-incompleteness} فرض کړئ $\Th{T}$ هره
$\omega$-سازګاره، !!{axiomatizable} تيوري ده چې~$\Th{Q}$ غځوي۔ نو
$\Th{T}$ بشپړه نۀ ده۔
\end{thm}

source:
\begin{proof}
  If $\Th{T}$ is $\omega$-consistent, it is consistent, so $\Th{T}
  \Proves/ !G_\Th{T}$ by \olref{lem:cons-G-unprov}.  By
  \olref{lem:omega-cons-G-unref}, $\Th{T} \Proves/ \lnot !G_\Th{T}$.
  This means that $\Th{T}$ is incomplete, since it !!{derive}s neither
  $!G_\Th{T}$ nor $\lnot !G_\Th{T}$.
\end{proof}

target:
\begin{proof}
  که~$\Th{T}$، $\omega$-سازګاره وي، نو سازګاره ده؛ ځکه د
  \olref{lem:cons-G-unprov} له مخې $\Th{T}
  \Proves/ !G_\Th{T}$۔ د~\olref{lem:omega-cons-G-unref} له مخې
  $\Th{T} \Proves/ \lnot !G_\Th{T}$۔ دا معنا لري چې~$\Th{T}$
  ناتکميله ده، ځکه نۀ~$!G_\Th{T}$ او نۀ~$\lnot !G_\Th{T}$
  !!{derive}s کوي۔
\end{proof}

source:
\begin{thm}
\ollabel{thm:rosser}
Let $\Th{T}$ be any consistent, !!{axiomatizable} theory
extending $\Th{Q}$. Then $\Th{T}$ is not complete.
\end{thm}

target:
\begin{thm}
\ollabel{thm:rosser}
فرض کړئ $\Th{T}$ هره سازګاره او !!{axiomatizable} تيوري ده چې
$\Th{Q}$ غځوي۔ نو~$\Th{T}$ بشپړه نۀ ده۔
\end{thm}

source:
By the fixed-point lemma, there is a formula $!R_\Th{T}$ such that
\begin{equation}
  \Th{Q} \Proves !R_\Th{T} \liff \lnot \ORProv[\Th{T}](\gn{!R_\Th{T}}).
  \ollabel{RT}
\end{equation}
In contrast to the proof of \olref[1in]{thm:first-incompleteness},
here we claim that if $\Th{T}$ is consistent, $\Th{T}$ doesn't !!{derive}
$!R_\Th{T}$, and $\Th{T}$ also doesn't !!{derive} $\lnot !R_\Th{T}$. (In
other words, we don't need the assumption of $\omega$-consistency.)

target:
د ثابت ټکي د لمې له مخې داسې فورمول~$!R_\Th{T}$ شته چې
\begin{equation}
  \Th{Q} \Proves !R_\Th{T} \liff \lnot \ORProv[\Th{T}](\gn{!R_\Th{T}}).
  \ollabel{RT}
\end{equation}
د~\olref[1in]{thm:first-incompleteness} د ثبوت برعکس، دلته دعوه
دا ده چې که~$\Th{T}$ سازګاره وي، نو~$\Th{T}$، $!R_\Th{T}$
نۀ !!{derive} کوي، او~$\Th{T}$، $\lnot !R_\Th{T}$ هم نۀ !!{derive} کوي۔
(په نورو ټکو، د $\omega$-سازګارۍ فرض ته اړتيا نشته۔)

source:
\begin{thm}
\ollabel{thm:second-incompleteness} 
Assuming $\Th{PA}$ is consistent, then $\Th{PA}$ does not !!{derive}
$\OCon[\Th{PA}]$.
\end{thm}

target:
