source:
\begin{thm}
\ollabel{thm:sol-no-ls} The L\"owenheim--Skolem Theorem fails for
second-order logic: There are !!{sentence}s with infinite models but
no !!{enumerable} models.
\end{thm}

target:
\begin{thm}
\ollabel{thm:sol-no-ls} د لوېنهايم--سکولم قضيه د دويمې درجې منطق
دپاره نۀ صدق کوي: داسې !!{sentence}s شته چې نامتناهي مدلونه لري،
خو !!{enumerable} مدل نۀ لري۔
\end{thm}

source:
\begin{thm}
There are !!{sentence}s with !!{denumerable} but no
!!{nonenumerable} models.
\end{thm}

target:
\begin{thm}
داسې !!{sentence}s شته چې !!{denumerable} مدلونه لري، خو
!!{nonenumerable} مدلونه نۀ لري۔
\end{thm}

source:
\begin{proof}
$\fn{Count} \land \fn{Inf}$ is true in $\Nat$ but not in any
  !!{structure}~$\Struct{M}$ with $\Domain{M}$ !!{nonenumerable}.
\end{proof}

target:
\begin{proof}
$\fn{Count} \land \fn{Inf}$ په~$\Nat$ کښې رښتيا ده، خو په هېڅ داسې
  !!{structure}~$\Struct{M}$ کښې نۀ ده رښتيا چې $\Domain{M}$ ئې
  !!{nonenumerable} وي۔
\end{proof}

source:
\begin{prop}
The !!{formula} $\lforall[x][(X(x) \lif Y(x))]$ defines the subset
relation, i.e., $\Sat{M}{\lforall[x][(X(x) \lif Y(x))]}[s]$ iff $s(X)
\subseteq s(Y)$.
\end{prop}

target:
\begin{prop}
!!{formula} $\lforall[x][(X(x) \lif Y(x))]$ د فرعي سټ اړيکه
تعريفوي؛ يعنې $\Sat{M}{\lforall[x][(X(x) \lif Y(x))]}[s]$ هله او
يوازې هله چې $s(X) \subseteq s(Y)$۔
\end{prop}

source:
\begin{prop}
The !!{formula} $\lforall[x][(X(x) \liff Y(x))]$ defines the identity
relation on sets, i.e., $\Sat{M}{\lforall[x][(X(x) \liff Y(x))]}[s]$
iff $s(X) = s(Y)$.
\end{prop}

target:
\begin{prop}
!!{formula} $\lforall[x][(X(x) \liff Y(x))]$ د سټونو د يووالي
اړيکه تعريفوي؛ يعنې $\Sat{M}{\lforall[x][(X(x) \liff Y(x))]}[s]$
هله او يوازې هله چې $s(X) = s(Y)$۔
\end{prop}

source:
\begin{prop}
The !!{formula} $\lexists[x][X(x)]$ defines the property of being
non-empty, i.e., $\Sat{M}{\lexists[x][X(x)]}[s]$ iff $s(X) \neq
\emptyset$.
\end{prop}

target:
\begin{prop}
!!{formula} $\lexists[x][X(x)]$ د ناتشوالي خاصيت تعريفوي؛ يعنې
$\Sat{M}{\lexists[x][X(x)]}[s]$ هله او يوازې هله چې $s(X) \neq
\emptyset$۔
\end{prop}

source:
\begin{prop}
The formula
\begin{multline*}
  \lexists[u][(\lforall[x][(X(x) \lif Y(u(x)))] \land {}\\
    \lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif \eq[x][y])]]
  \land {} \\\lforall[y][(Y(y) \lif \lexists[x][(X(x)
      \land \eq[y][u(x)])])])]
\end{multline*}
defines the relation of being equinumerous with.
\end{prop}

target:
\begin{prop}
لاندې فورمول
\begin{multline*}
  \lexists[u][(\lforall[x][(X(x) \lif Y(u(x)))] \land {}\\
    \lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif \eq[x][y])]]
  \land {} \\\lforall[y][(Y(y) \lif \lexists[x][(X(x)
      \land \eq[y][u(x)])])])]
\end{multline*}
د همشمېره‌والي اړيکه تعريفوي۔
\end{prop}

source:
\begin{prop}
The !!{sentence} $\lforall[X][\lforall[Y][((\cardle{X}{Y} \land
    \cardle{Y}{X}) \lif \cardeq{X}{Y})]]$ is valid.
\end{prop}

target:
\begin{prop}
!!{sentence} $\lforall[X][\lforall[Y][((\cardle{X}{Y} \land
    \cardle{Y}{X}) \lif \cardeq{X}{Y})]]$ معتبره ده۔
\end{prop}

source:
\begin{explain}
Just as we can express that the domain is finite or infinite,
!!{enumerable} or !!{nonenumerable}, we can define the property of a
subset of~$\Domain{M}$ being finite or infinite, !!{enumerable} or
!!{nonenumerable}.
\end{explain}

target:
\begin{explain}
لکه څنګه چې د تعريف ساحې متناهي يا نامتناهي، !!{enumerable} يا
!!{nonenumerable} والے څرګندولے شو، همداسې د~$\Domain{M}$ د يوه
فرعي سټ متناهي يا نامتناهي، !!{enumerable} يا !!{nonenumerable}
والے هم تعريفولے شو۔
\end{explain}

source:
\begin{prop}
The formula $\fn{Inf}(X) \ident$
\begin{multline*}
\lexists[u][(\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif 
      \eq[x][y])]] \land {} \\\lexists[y][(X(y) \land \lforall[x][(X(x)
      \lif \eq/[y][u(x)])]])]
\end{multline*}
is satisfied with respect to a variable assignment~$s$ iff $s(X)$ is
infinite.
\end{prop}

\begin{prop}
The formula $\fn{Count}(X) \ident $
\begin{multline*}
\lexists[z][\lexists[u][(X(z) \land 
    \lforall[x][(X(x) \lif X(u(x)))] \land {} \\ \lforall[Y][((Y(z) \land
      \lforall[x][(Y(x) \lif Y(u(x)))]) \lif X = Y])]])
\end{multline*}
is satisfied with respect to a variable assignment~$s$ iff $s(X)$ is
!!{enumerable}.
\end{prop}

\begin{defn}
If $R \subseteq \Domain{M}^2$, then \emph{$x$ $R$-codes} $\Setabs{y
  \in \Domain{M}}{R(x, y)}$.
\end{defn}

target:
\begin{defn}
که $R \subseteq \Domain{M}^2$ وي، نو \emph{$x$ د~$R$ له مخې}
سټ $\Setabs{y
  \in \Domain{M}}{R(x, y)}$ \emph{کوډوي}۔
\end{defn}

source:
\begin{prop}
The !!{formula}
  \[
  \fn{Codes}(x, R, Z) \ident \lforall[y][(Z(y) \liff
    R(x, y))]
  \]
expresses that $s(x)$ $s(R)$-codes $s(Z)$.  The
!!{formula} 
\begin{multline*}
  \fn{Pow}(Y, R, X) \ident \\
  \lforall[Z][(Z \subseteq X \lif \lexists[x][(Y(x) \land
    \fn{Codes}(x, R, Z))])] \land {} \\ \lforall[x][(Y(x) \lif
  \lforall[Z][(\fn{Codes}(x, R, Z) \lif Z \subseteq X)]]
\end{multline*}
expresses that $s(Y)$ $s(R)$-codes the power set of~$s(X)$, i.e., the
elements of $s(Y)$ $s(R)$-code exactly the subsets of $s(X)$.
\end{prop}

\begin{prop}
The sentence
\begin{multline*}
  \lforall[X][\lforall[Y][\lforall[R][(\fn{Pow}(Y, R, X) \lif \\
      \lnot \lexists[u][(\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif
            \eq[x][y])]] \land {}\\
        \lforall[x][(Y(x) \lif X(u(x)))])])]]]
\end{multline*}
is valid.
\end{prop}

target:
\begin{prop}
لاندې جمله
\begin{multline*}
  \lforall[X][\lforall[Y][\lforall[R][(\fn{Pow}(Y, R, X) \lif \\
      \lnot \lexists[u][(\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif
            \eq[x][y])]] \land {}\\
        \lforall[x][(Y(x) \lif X(u(x)))])])]]]
\end{multline*}
معتبره ده۔
\end{prop}

source:
\begin{prop}
If $\cardle{\Real}{\Domain{M}}$, then the !!{formula}
\begin{multline*}
\fn{Cont}(Y) \ident 
\lexists[X][\lexists[R][((\fn{Aleph}_0(X) \land
      \fn{Pow}(Y, R, X)) \land \\ 
      \lforall[x][\lforall[y][((Y(x) \land {} 
      Y(y) \land \lforall[z][R(x,z) \liff R(y,z)]) \lif \eq[x][y])]])]]
\end{multline*}
expresses that $\cardeq{s(Y)}{\Real}$.
\end{prop}

target:
\begin{prop}
که $\cardle{\Real}{\Domain{M}}$ وي، نو !!{formula}
\begin{multline*}
\fn{Cont}(Y) \ident
\lexists[X][\lexists[R][((\fn{Aleph}_0(X) \land
      \fn{Pow}(Y, R, X)) \land \\
      \lforall[x][\lforall[y][((Y(x) \land {}
      Y(y) \land \lforall[z][R(x,z) \liff R(y,z)]) \lif \eq[x][y])]])]]
\end{multline*}
دا څرګندوي چې $\cardeq{s(Y)}{\Real}$۔
\end{prop}

source:
\begin{prop}
$\cardeq{\Domain{M}}{\Real}$ iff
\begin{multline*}
  \Sat{M}{\lexists[X][\lexists[Y][\lexists[R][(\fn{Aleph}_0(X) \land \fn{Pow}(Y, R, X) \land \\
          \lexists[u][(\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif \eq[x][y])]] \land {} \\\lforall[y][(Y(y) \lif \lexists[x][\eq[y][u(x)]])])])]]]}.
        \end{multline*}
  \end{prop}

target:
\begin{prop}
$\cardeq{\Domain{M}}{\Real}$ هله او يوازې هله چې
\begin{multline*}
  \Sat{M}{\lexists[Y][(\fn{Cont}(Y) \land {} \\
    \lexists[u][(\lforall[x][Y(u(x))] \land {}
      \lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif \eq[x][y])]] \land {} \\
      \lforall[y][(Y(y) \lif \lexists[x][\eq[y][u(x)]])])])]}.
\end{multline*}
\end{prop}
\textbf{د ژباړې د نسخې سمون (OLSOL-011):} د سرچينې
ښودل شوې جمله يوازې دا تضمينوي چې تعريف ساحه لږ تر لږه
د پيوستار هومره لويه ده؛ د کټ مټ برابرې اندازې دعوه
ترې نۀ راځي۔ دلته د کوډونو له پيوستاري سټ سره د ټولې
تعريف ساحې د يو پر يو او پر سر تابع شرط راغلے دے۔

source:
\begin{explain}
The Continuum Hypothesis is the statement that the size of the
continuum is the first !!{nonenumerable} cardinality, i.e, that
$\Pow{\Nat}$ has size~$\aleph_1$. 
\end{explain}

target:
\begin{explain}
د پيوستار فرضيه وايي چې د پيوستار اندازه لومړۍ
!!{nonenumerable} شمېرنيزه اندازه ده؛ يعنې
$\Pow{\Nat}$ د~$\aleph_1$ اندازه لري۔
\end{explain}

source:
\begin{prop}
The Continuum Hypothesis is true iff \[\fn{CH} \ident
\lforall[X][(\fn{Aleph}_1(X) \liff \fn{Cont}(X))]\] is valid.
\end{prop}

target:
\begin{prop}
د پيوستار فرضيه هله او يوازې هله رښتيا ده چې
\[\fn{CH} \ident
\lforall[X][(\fn{Aleph}_1(X) \liff \fn{Cont}(X))]\]
معتبره وي۔
\end{prop}

source:
\begin{prop}
The Continuum Hypothesis is false iff \[\fn{NCH} \ident
\lforall[X][(\fn{Cont}(X) \lif \lexists[Y][(Y \subseteq X \land \lnot
    \fn{Count}(Y) \land \lnot \cardeq{X}{Y})])]\] is valid.
\end{prop}

