\begin{defn}[Change of bound variable, $\aconvone$]
  If a term $M$ contains an occurrence of $\lambd[x][N]$, $y \notin
  \FV{N}$, and $\Subst{N}{y}{x}$ is defined, then replacing this occurrence
  by 
  \begin{equation*}
    \lambd[y][\Subst{N}{y}{x}]
  \end{equation*}
  resulting in $M'$ is called a \emph{change of bound variable}, written
  as $M \redone[\alpha] M'$.
\end{defn}

target:
\begin{defn}[د تړلي متغير د نوم بدلون، $\aconvone$]
  که ترم~$M$ د $\lambd[x][N]$ يو مورد ولري، $x\neq y$ وي،
  $y \notin \FV{N}$ وي او $\Subst{N}{y}{x}$ ټاکلے وي، نو د دې مورد
  په
  \begin{equation*}
    \lambd[y][\Subst{N}{y}{x}]
  \end{equation*}
  بدلول، چې پايله ئې~$M'$ ده، \emph{د تړلي متغير د نوم بدلون}
  بلل کېږي او $M \redone[\alpha] M'$ ليکل کېږي۔
  \textbf{د ژباړې د نسخې سمون (OLLAM-017):} د سرچينې په دې
  لومړي تعريف کښې د دوو نومونو نابرابري نۀ وه ويل شوې، خو
  راتلونکے معادل تعريف او استقرايي قاعده ئې شرط بولي۔
\end{defn}

source:
\begin{defn}[Compatibility of relation]
  A relation $R$ on terms is said to be \emph{compatible}
  if it satisfies following conditions:
  \begin{enumerate}
  \item If $R N N'$ then $R \lambd[x][N] \lambd[x][N']$
  \item If $R P P'$ then $R (PQ) (P'Q)$
  \item If $R Q Q'$ then $R (PQ) (PQ')$
  \end{enumerate}
\end{defn}

target:
\begin{defn}[د اړيکې سازګارتيا]
  پر ترمونو يوه اړيکه~$R$ \emph{سازګاره} بلل کېږي که دا شرطونه
  پوره کړي:
  \begin{enumerate}
  \item که $R N N'$ وي، نو $R \lambd[x][N] \lambd[x][N']$ وي۔
  \item که $R P P'$ وي، نو $R (PQ) (P'Q)$ وي۔
  \item که $R Q Q'$ وي، نو $R (PQ) (PQ')$ وي۔
  \end{enumerate}
\end{defn}

source:
Thus let's rephrase the definition:
\begin{defn}[Change of bound variable, $\aconvone$]
  \emph{Change of bound variable} ($\redone[\alpha]$) is 
  the smallest compatible relation on terms satisfying following
  condition:
  \begin{align*}
    &\lambd[x][N] \redone[\alpha] \lambd[y][\Subst{N}{y}{x}] && \text{if
      $x \neq y$, $y \notin \FV{N}$} \\
    & &&\text{and $\Subst{N}{y}{x}$ is defined}
  \end{align*}
\end{defn}

