  که $P \aconvone Q$ وي، نو $\FV{P} = \FV{Q}$ وي۔
\end{lem}

source:
\begin{proof}
  By induction on the !!{derivation} of $P \aconvone Q$.
  \begin{enumerate}
  \item If the last rule is \olref{defn:aconvone4}, then $P$ is of the
    form $\lambd[x][N]$ and $Q$ of the form
    $\lambd[y][\Subst{N}{y}{x}]$, with $x \neq y$, $y \notin \FV{N}$
    and $\Subst{N}{y}{x}$ defined. We distinguish cases according to
    whether $x \in \FV{N}$:
    \begin{enumerate}
    \item If $x \in FV(N)$, then:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]} &=
        \FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = ((\FV{N} \setminus \{x\}) \cup \{y\}) \setminus \{y\}
         && \text{ by \olref[sub]{thm:infv}} \\
        & = \FV{N} \setminus \{x\} \\
        & = \FV{\lambd[x][N]}
      \end{align*}
    \item If $x \notin FV(N)$, then:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]}
        & = FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = \FV{N} \setminus \{x\}
         && \text{by \olref[sub]{thm:notinfv}} \\
        & = \FV{\lambd[x][N]}.
      \end{align*}
    \end{enumerate}
  \item The other three cases are left as exercises. 
  \end{enumerate}
\end{proof}

target:
\begin{proof}
  د $P \aconvone Q$ د !!{derivation} پر بنسټ استقرا کوو۔
  \begin{enumerate}
  \item که وروستۍ قاعده \olref{defn:aconvone4} وي، نو $P$ د
    $\lambd[x][N]$ او $Q$ د
    $\lambd[y][\Subst{N}{y}{x}]$ په بڼه دي؛ دلته $x \neq y$،
    $y \notin \FV{N}$ او $\Subst{N}{y}{x}$ ټاکلے دے۔ اوس د
    $x \in \FV{N}$ او د دې د نفي حالتونه بېلوو:
    \begin{enumerate}
    \item که $x \in \FV{N}$ وي، نو:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]} &=
        \FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = ((\FV{N} \setminus \{x\}) \cup \{y\}) \setminus \{y\}
         && \text{د \olref[sub]{thm:infv} له مخې} \\
        & = \FV{N} \setminus \{x\} \\
        & = \FV{\lambd[x][N]}
      \end{align*}
    \item که $x \notin \FV{N}$ وي، نو:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]}
        & = \FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = \FV{N} \setminus \{y\}
         && \text{د \olref[sub]{thm:notinfv} له مخې} \\
        & = \FV{N} && y \notin \FV{N} \\
        & = \FV{N} \setminus \{x\} && x \notin \FV{N} \\
        & = \FV{\lambd[x][N]}.
      \end{align*}
    \end{enumerate}
    \textbf{د ژباړې د نسخې سمون (OLLAM-020):} د سرچينې په
    درېو ځايونو کښې د ازادو متغيرونو نښه له خپل ټاکلي ماکرو
    پرته ليکل شوې وه۔ د دويم حالت حساب هم له منځنيو لازمو
    مساواتو سره بشپړ شوے دے۔
  \item نور درې حالتونه د تمرين دپاره پرېښودل شوي دي۔
  \end{enumerate}
\end{proof}

