\begin{thm}\ollabel{thm:sub}
  For any $M$, $R$, and~$y$, there exists $M'$ such that $M \aeq M'$
  and $\Subst{M'}{R}{y}$ is defined. Moreover, if there is another
  pair $M'' \aeq M$ and $R''$ where $\Subst{M''}{R''}{y}$ is defined
  and $R'' \aeq R$, then $\Subst{M'}{R}{y} \aeq \Subst{M''}{R''}{y}$.
\end{thm}

    Moreover, if there is another $N''$ and $R''$ satisfying the same
    conditions,
    \begin{multline*}
      \Subst{(\lambd[z][\Subst{N''}{z}{x}])}{R''}{y} =\\
    \begin{aligned}
      &= \lambd[z][\Subst{\Subst{N''}{z}{x}}{R''}{y}] \\
      &= \lambd[z][\Subst{\Subst{N''}{z}{x}}{R}{y}] && \text{by
        \olref{lem:sub:R}}\\
      &=\lambd[z][\Subst{\Subst{N'}{z}{x}}{R}{y}]
      && \text{by inductive
        hypothesis}\\
      &=\Subst{(\lambd[z][\Subst{N'}{z}{x}])}{R}{y}
    \end{aligned}
    \end{multline*}
    \item $M$ is of the form $(PQ)$: Exercise.
  \end{enumerate}
\end{proof}

target:
    سربېره پر دې، که بل~$N''$ او~$R''$ هماغه شرطونه پوره کړي،
    سرچينه لاندې حساب راوړي:
    \begin{multline*}
      \Subst{(\lambd[z][\Subst{N''}{z}{x}])}{R''}{y} =\\
    \begin{aligned}
      &= \lambd[z][\Subst{\Subst{N''}{z}{x}}{R''}{y}] \\
      &= \lambd[z][\Subst{\Subst{N''}{z}{x}}{R}{y}] && \text{د
        \olref{lem:sub:R} له مخې}\\
      &=\lambd[z][\Subst{\Subst{N'}{z}{x}}{R}{y}]
      && \text{د استقرا د
        فرضيې له مخې}\\
      &=\Subst{(\lambd[z][\Subst{N'}{z}{x}])}{R}{y}
    \end{aligned}
    \end{multline*}
    \textbf{د ژباړې د نسخې سمون (OLLAM-023):} په دې لړۍ کښې
    يادې شوې لمه او د استقرا فرضيه يوازې الفا-معادلتوب ورکوي،
    نه نحوي برابري؛ د سرچينې د مساواتو نښې دلته د بشپړ ثبوت
    په توګه نۀ منل کېږي۔ سربېره پر دې، لړۍ يوازې ځانګړي بيا
    نومول شوي ترمونه پرتله کوي؛ د قضيې د هرې ممکنې بلې
    الفا-معادلې جوړې د پايلو يوګونتيا پکې نۀ ده ثابته شوې۔
    \item که $M$ د $(PQ)$ په بڼه وي: تمرين۔
  \end{enumerate}
\end{proof}

