\begin{defn}
  De Bruijn terms are inductively defines as follows:
  \begin{enumerate}
  \item $n$, where $n$ is any natural number.
  \item $PQ$, where $P$ and $Q$ are both De Bruijn terms.
  \item $\lambd[][N]$, where $N$ is a De Bruijn term.
  \end{enumerate}
\end{defn}

target:
\begin{defn}
  د دې بروين ترمونه په استقرايي ډول داسې تعريفېږي:
  \begin{enumerate}
  \item $n$، چې $n$ هر طبيعي عدد وي۔
  \item $PQ$، چې $P$ او $Q$ دواړه د دې بروين ترمونه وي۔
  \item $\lambd[][N]$، چې $N$ د دې بروين ترم وي۔
  \end{enumerate}
\end{defn}

