\begin{defn}
  \begin{enumerate}
  \item $\lambd[x][N]$ هغه ټولګے دے چې
    $\lambd[x][\rep{N}]$ پکې شامل وي۔
  \item $PQ$ هغه ټولګے دے چې $\rep{P}\rep{Q}$ پکې شامل وي۔
  \end{enumerate}
