\begin{defn}[$\beta$-reduction, $\bred$] \ollabel{defn:betared}
  \emph{$\beta$-reduction} ($\bred$) is the smallest reflexive,
  transitive relation on terms containing $\bredone$.  We say $P$ is
  $\beta$-reduced to $Q$ if $P \bred Q$.
\end{defn}

